import type { BuildFormat } from './build-info.js';

const buckets = [320, 360, 375, 390, 414, 720, 768, 900, 1024, 1080, 1280, 1366, 1440, 1536, 1920, 2560] as const;

export function bucketDimension(value: number): (typeof buckets)[number] {
  return buckets.reduce((closest, bucket) => Math.abs(bucket - value) < Math.abs(closest - value) ? bucket : closest);
}

export interface BehaviorSnapshot {
  loadTimeMs: number;
  mouseMoves: number;
  mouseClicks: number;
  keyPresses: number;
  scrollEvents: number;
}

const NOOP_SNAPSHOT: BehaviorSnapshot = { loadTimeMs: 0, mouseMoves: 0, mouseClicks: 0, keyPresses: 0, scrollEvents: 0 };

export function createBehaviorTracker(win: Window): {
  snapshot(): BehaviorSnapshot;
  destroy(): void;
} {
  const state = { mouseMoves: 0, mouseClicks: 0, keyPresses: 0, scrollEvents: 0 };
  const loadTimeMs = Math.round(performance.now());

  function onMove() { state.mouseMoves += 1; }
  function onClick() { state.mouseClicks += 1; }
  function onKey() { state.keyPresses += 1; }
  function onScroll() { state.scrollEvents += 1; }

  win.addEventListener('mousemove', onMove, { passive: true });
  win.addEventListener('click', onClick, { passive: true, capture: true });
  win.addEventListener('keydown', onKey, { passive: true, capture: true });
  win.addEventListener('scroll', onScroll, { passive: true, capture: true });

  return {
    snapshot(): BehaviorSnapshot {
      return {
        loadTimeMs,
        mouseMoves: state.mouseMoves,
        mouseClicks: state.mouseClicks,
        keyPresses: state.keyPresses,
        scrollEvents: state.scrollEvents,
      };
    },
    destroy() {
      win.removeEventListener('mousemove', onMove);
      win.removeEventListener('click', onClick, true);
      win.removeEventListener('keydown', onKey, true);
      win.removeEventListener('scroll', onScroll, true);
    },
  };
}

export function collectSignals(input: { buildInfo: { version: string; format: BuildFormat }; window: Window; navigator: Navigator; screen: Screen; behavior?: BehaviorSnapshot; theme?: 'light' | 'dark' }) {
  let localStorageAvailable = false;
  try { localStorageAvailable = Boolean(input.window.localStorage); } catch { localStorageAvailable = false; }
  const beh = input.behavior ?? NOOP_SNAPSHOT;
  return {
    schemaVersion: 1 as const,
    environment: {
      language: input.navigator.language || 'unknown',
      timezoneOffsetMinutes: new Date().getTimezoneOffset(),
      screenWidthBucket: bucketDimension(input.screen.width),
      screenHeightBucket: bucketDimension(input.screen.height),
      viewportWidthBucket: bucketDimension(input.window.innerWidth),
      viewportHeightBucket: bucketDimension(input.window.innerHeight),
      colorDepth: input.screen.colorDepth || 24,
      hardwareConcurrencyBucket: Math.min(32, Math.max(1, input.navigator.hardwareConcurrency || 1)),
      maxTouchPoints: Math.min(20, input.navigator.maxTouchPoints || 0),
    },
    capabilities: {
      webdriver: Boolean(input.navigator.webdriver),
      cookiesEnabled: input.navigator.cookieEnabled,
      localStorageAvailable,
      pointerEvent: 'PointerEvent' in input.window,
      touchEvent: 'TouchEvent' in input.window,
    },
    sdk: { version: input.buildInfo.version, build: input.buildInfo.format },
    loadTimeMs: beh.loadTimeMs,
    mouseMoves: beh.mouseMoves,
    mouseClicks: beh.mouseClicks,
    keyPresses: beh.keyPresses,
    scrollEvents: beh.scrollEvents,
    theme: input.theme ?? 'light',
  };
}
