import { BRAND_STYLES, createBrandLockup } from '../brand.js';
import { prepareImages, type ImagePreparation } from '../media.js';
import { PointerTelemetryCollector, type PointerDrag } from '../pointer-telemetry.js';
import { renderPowOverlay, type PowOverlayHandle, type PowRevealResult } from '../pow-overlay.js';
import type { PowParameters } from '../pow.js';
import { COMPONENT_STYLES, HOST_RESET, ROTATE_PUZZLE_STYLES, SPATIAL_STYLES, SUCCESS_FEEDBACK_STYLES } from '../styles.js';

export interface RotatePuzzleChallengeData {
  schemaVersion: 1;
  interactionNonce: string;
  fixedImage: string;
  rotatingImage: string;
  imageSize: number;
  rotatingPart: 'ring' | 'inner';
  maxRotationDegrees: number;
  direction: -1 | 1;
  pow: PowParameters;
}

export interface RotatePuzzleResponse {
  schemaVersion: 1;
  interactionNonce: string;
  finalPosition: number;
  powNonce: number;
}

export type RotatePuzzleTelemetry = { schemaVersion: 1; mode: 'pointer'; drag: PointerDrag; powActualMs: number };

export interface RotatePuzzleRendererOptions {
  data: RotatePuzzleChallengeData;
  restoreFocus: HTMLElement;
  onSubmit(response: RotatePuzzleResponse, telemetry: RotatePuzzleTelemetry): void;
  onRefresh(): void;
  onClose(): void;
  onMediaError?(error: Error): void;
}

export interface RotatePuzzleRendererHandle {
  readonly ready: Promise<void>;
  setBusy(busy: boolean): void;
  setRefreshing(refreshing: boolean): void;
  lock(): void;
  focus(): void;
  showSuccess(): Promise<void>;
  destroy(): void;
}

function iconButton(label: string, pathData: string): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'cpt-icon-button';
  button.setAttribute('aria-label', label);
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  path.setAttribute('d', pathData);
  svg.append(path);
  button.append(svg);
  return button;
}

let dialogSequence = 0;

export function renderRotatePuzzle(container: HTMLElement | ShadowRoot, options: RotatePuzzleRendererOptions): RotatePuzzleRendererHandle {
  const style = document.createElement('style');
  style.textContent = `${HOST_RESET}${COMPONENT_STYLES}${BRAND_STYLES}${SPATIAL_STYLES}${SUCCESS_FEEDBACK_STYLES}${ROTATE_PUZZLE_STYLES}`;
  const overlay = document.createElement('div');
  overlay.className = 'cpt-overlay';
  const dialog = document.createElement('section');
  dialog.className = 'cpt-modal';
  dialog.setAttribute('role', 'dialog');
  dialog.setAttribute('aria-modal', 'true');
  const title = document.createElement('h2');
  title.id = `cpt-rotate-title-${++dialogSequence}`;
  title.className = 'cpt-title';
  title.textContent = '安全验证';
  dialog.setAttribute('aria-labelledby', title.id);
  const header = document.createElement('header');
  header.className = 'cpt-header';
  header.append(title);
  const body = document.createElement('div');
  body.className = 'cpt-body';
  const root = document.createElement('section');
  root.className = 'cpt-rotate';
  const instruction = document.createElement('p');
  instruction.className = 'cpt-rotate-instruction';
  instruction.textContent = options.data.rotatingPart === 'ring' ? '拖动滑块，旋转圆环还原图片' : '拖动滑块，旋转内圆还原图片';
  const stage = document.createElement('div');
  stage.className = 'cpt-rotate-stage';
  const track = document.createElement('div');
  track.className = 'cpt-rotate-track';
  const rail = document.createElement('span');
  rail.className = 'cpt-rotate-rail';
  const center = document.createElement('span');
  center.className = 'cpt-rotate-center';
  const handle = document.createElement('button');
  handle.type = 'button';
  handle.className = 'cpt-rotate-handle';
  handle.setAttribute('aria-label', '拖动旋转滑块');
  handle.textContent = '↔';
  track.append(rail, center, handle);
  root.append(instruction, stage, track);
  body.append(root);
  const footer = document.createElement('footer');
  footer.className = 'cpt-footer';
  const toolbar = document.createElement('div');
  toolbar.className = 'cpt-toolbar';
  const close = iconButton('关闭挑战', 'M6 6l12 12M18 6 6 18');
  const refresh = iconButton('刷新挑战', 'M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7');
  toolbar.append(close, refresh);
  footer.append(toolbar, createBrandLockup('footer'));
  dialog.append(header, body, footer);
  overlay.append(dialog);
  container.append(style, overlay);

  let destroyed = false;
  let locked = false;
  let busy = false;
  let refreshing = false;
  let position = 0;
  let preparation: ImagePreparation | undefined;
  let collector: PointerTelemetryCollector | undefined;
  let rotating: HTMLImageElement | undefined;
  let powOverlay: PowOverlayHandle | undefined;
  let powReveal: PowRevealResult | undefined;

  const renderPosition = (): void => {
    handle.style.left = `${(position + 1) * 50}%`;
    if (rotating) rotating.style.transform = `rotate(${Number((position * options.data.maxRotationDegrees * options.data.direction).toFixed(2))}deg)`;
  };
  const update = (): void => {
    const disabled = destroyed || locked || busy || refreshing || !powReveal;
    handle.disabled = disabled;
    close.disabled = disabled;
    refresh.disabled = disabled;
    root.setAttribute('aria-busy', String(busy || refreshing));
  };
  const abort = (): void => {
    collector?.abort();
    collector = undefined;
    root.dataset.picked = 'false';
    handle.style.cursor = 'grab';
  };
  const positionFrom = (event: PointerEvent): number => {
    const rect = track.getBoundingClientRect();
    const linear = Math.max(-1, Math.min(1, (event.clientX - rect.left) / Math.max(1, rect.width) * 2 - 1));
    const magnitude = Math.abs(linear);
    return Number((Math.sign(linear) * (magnitude > 0.86 ? 0.86 + (magnitude - 0.86) * 0.55 : magnitude)).toFixed(4));
  };
  const onPointerDown = (event: PointerEvent): void => {
    if (handle.disabled) return;
    const next = new PointerTelemetryCollector({ target: handle, rect: () => track.getBoundingClientRect() });
    if (!next.start(event)) return;
    collector = next;
    root.dataset.picked = 'true';
    handle.style.cursor = 'grabbing';
  };
  const onPointerMove = (event: PointerEvent): void => {
    if (!collector?.move(event)) return;
    position = positionFrom(event);
    renderPosition();
  };
  const onPointerUp = (event: PointerEvent): void => {
    const active = collector;
    if (!active) return;
    position = positionFrom(event);
    renderPosition();
    const drag = active.finish(event, 'rotate-puzzle-drag');
    collector = undefined;
    root.dataset.picked = 'false';
    handle.style.cursor = 'grab';
    if (drag && !destroyed && !locked && !busy && !refreshing && powReveal) options.onSubmit(
      { schemaVersion: 1, interactionNonce: options.data.interactionNonce, finalPosition: position, powNonce: powReveal.nonce },
      { schemaVersion: 1, mode: 'pointer', drag, powActualMs: powReveal.actualMs },
    );
  };
  const onPointerCancel = (event: PointerEvent): void => {
    collector?.cancel(event);
    abort();
  };
  const onBlur = (): void => abort();
  const onVisibility = (): void => { if (document.visibilityState === 'hidden') abort(); };
  const onClose = (): void => { if (!busy && !refreshing && powReveal) options.onClose(); };
  const onRefresh = (): void => { if (!busy && !refreshing && powReveal) options.onRefresh(); };
  const onKeyDown = (event: KeyboardEvent): void => { if (event.key === 'Escape') onClose(); };
  const cleanup = (): void => {
    if (destroyed) return;
    destroyed = true;
    abort();
    powOverlay?.destroy();
    powOverlay = undefined;
    preparation?.destroy();
    handle.removeEventListener('pointerdown', onPointerDown);
    handle.removeEventListener('pointermove', onPointerMove);
    handle.removeEventListener('pointerup', onPointerUp);
    handle.removeEventListener('pointercancel', onPointerCancel);
    close.removeEventListener('click', onClose);
    refresh.removeEventListener('click', onRefresh);
    overlay.removeEventListener('keydown', onKeyDown);
    window.removeEventListener('blur', onBlur);
    document.removeEventListener('visibilitychange', onVisibility);
    overlay.remove();
    style.remove();
    options.restoreFocus.focus();
  };

  handle.addEventListener('pointerdown', onPointerDown);
  handle.addEventListener('pointermove', onPointerMove);
  handle.addEventListener('pointerup', onPointerUp);
  handle.addEventListener('pointercancel', onPointerCancel);
  close.addEventListener('click', onClose);
  refresh.addEventListener('click', onRefresh);
  overlay.addEventListener('keydown', onKeyDown);
  window.addEventListener('blur', onBlur);
  document.addEventListener('visibilitychange', onVisibility);

  preparation = prepareImages([options.data.fixedImage, options.data.rotatingImage]);
  const [fixedImage, rotatingImage] = preparation.images as [HTMLImageElement, HTMLImageElement];
  fixedImage.className = 'cpt-rotate-fixed';
  rotatingImage.className = 'cpt-rotate-piece';
  fixedImage.alt = '';
  rotatingImage.alt = '';
  fixedImage.hidden = true;
  rotatingImage.hidden = true;
  rotating = rotatingImage;
  stage.append(fixedImage, rotatingImage);
  powOverlay = renderPowOverlay(stage, {
    imageUrl: options.data.fixedImage,
    pow: options.data.pow,
    onRevealed: (result) => {
      powReveal = result;
      update();
    },
    onError: (error) => {
      if (!destroyed) options.onMediaError?.(error);
    },
  });
  update();
  renderPosition();
  const ready = preparation.ready.then((images) => {
    if (destroyed) return;
    // 固定图是完整参照图（含圆心品牌标记），保持显示在切分网格之上；旋转图保持在最上层
    rotatingImage.hidden = false;
    rotating = images[1];
    renderPosition();
  });
  void ready.catch((error: unknown) => { if (!destroyed) options.onMediaError?.(error instanceof Error ? error : new Error('CORPTCHA_MEDIA_ERROR')); });

  return {
    ready,
    setBusy: (value) => { busy = value; update(); },
    setRefreshing: (value) => { refreshing = value; if (value) abort(); update(); },
    lock: () => { locked = true; abort(); update(); },
    focus: () => handle.focus(),
    showSuccess: async () => {
      root.dataset.success = 'true';
      await new Promise<void>((resolve) => setTimeout(resolve, 220));
    },
    destroy: cleanup,
  };
}
