import { BRAND_STYLES, createBrandLockup } from '../brand.js';
import { GhostStreamPlayer } from '../ghost-stream.js';
import { renderPowOverlay, type PowOverlayHandle, type PowRevealResult } from '../pow-overlay.js';
import type { PowParameters } from '../pow.js';
import { COMPONENT_STYLES, HOST_RESET } from '../styles.js';

export type CharacterChallenge =
  | Readonly<{ kind: 'decoy'; prompt: string; image: string; pow: PowParameters }>
  | Readonly<{ kind: 'ghost'; prompt: string; mediaType: 'application/vnd.ghost-font-stream'; mediaUrl: string; loadMedia(signal: AbortSignal): Promise<Response> }>;

export interface CharacterRendererOptions {
  challenge: CharacterChallenge;
  restoreFocus: HTMLElement;
  onSubmit(answer: string, pow: PowRevealResult | undefined): void;
  onRefresh(): void;
  onClose(): void;
  onMediaError?(error: Error): void;
}

export interface CharacterRendererHandle {
  readonly ready: Promise<void>;
  setSubmitting(submitting: boolean): void;
  setRefreshing(refreshing: boolean): void;
  showSuccess(): void;
  startLeaving(): void;
  replace(challenge: CharacterChallenge): Promise<void>;
  focus(): void;
  destroy(): void;
}

const CHARACTER_STYLES = '.cpt-overlay{position:fixed;z-index:2147483647;inset:0;display:grid;place-items:center;padding:16px;background:var(--cpt-overlay);animation:cpt-overlay-in .18s ease-out both}.cpt-modal{width:min(392px,calc(100vw - 32px));overflow:visible;border:1px solid var(--cpt-border);border-radius:8px;background:var(--cpt-surface);box-shadow:var(--cpt-shadow);animation:cpt-dialog-in .2s cubic-bezier(.2,.8,.2,1) both}.cpt-overlay--leaving{animation:cpt-overlay-out .16s ease-in both}.cpt-overlay--leaving .cpt-modal{animation:cpt-dialog-out .16s ease-in both}.cpt-header{padding:18px 20px 13px}.cpt-title{margin:0;font-size:16px;font-weight:650;line-height:23px;color:var(--cpt-text)}.cpt-instruction{margin:3px 0 0;color:var(--cpt-muted);font-size:13px;line-height:19px}.cpt-body{padding:0 20px 16px}.cpt-media-stage{position:relative;display:grid;width:100%;min-height:120px;overflow:hidden;place-items:center;border:1px solid var(--cpt-border);border-radius:6px;background:var(--cpt-stage)}.cpt-media-stage--decoy img{display:block;width:100%;height:auto}.cpt-media-stage--ghost{aspect-ratio:16/9}.cpt-media-stage--ghost canvas{width:100%;height:100%;object-fit:contain}.cpt-media-refresh{position:absolute;z-index:3;inset:0;display:grid;place-items:center;background:var(--cpt-refresh-overlay)}.cpt-spinner{width:24px;height:24px;border:2px solid color-mix(in srgb,var(--cpt-accent) 22%,transparent);border-top-color:var(--cpt-accent);border-radius:50%;animation:cpt-spin .8s linear infinite}.cpt-success{position:absolute;z-index:2;inset:0;display:grid;align-content:center;justify-items:center;gap:7px;background:var(--cpt-success-overlay);color:var(--cpt-success-icon-text);font-size:14px;font-weight:650;opacity:0;visibility:hidden;transition:opacity .12s ease}.cpt-success-icon{display:grid;width:36px;height:36px;place-items:center;border-radius:50%;background:var(--cpt-success-icon-bg);color:var(--cpt-success-icon-text);font-size:23px}.cpt-modal--success .cpt-success{opacity:1;visibility:visible}.cpt-answer-row{display:flex;gap:8px;margin-top:11px}.cpt-answer{min-width:0;min-height:42px;flex:1;padding:0 12px;border:1px solid var(--cpt-border);border-radius:6px;outline:0;background:var(--cpt-surface);color:var(--cpt-text);font:600 15px/1 var(--cpt-font,system-ui);letter-spacing:0;text-transform:uppercase;transition:border-color .14s ease,box-shadow .14s ease}.cpt-answer:hover{border-color:var(--cpt-hover)}.cpt-answer:focus{border-color:var(--cpt-focus);box-shadow:0 0 0 3px color-mix(in srgb,var(--cpt-focus) 15%,transparent)}.cpt-submit{display:inline-flex;min-width:88px;min-height:42px;padding:0 15px;align-items:center;justify-content:center;gap:7px;border:1px solid var(--cpt-accent);border-radius:6px;background:var(--cpt-accent);color:var(--cpt-button-text);font-weight:650;cursor:pointer;transition:filter .14s ease,transform .1s ease,opacity .14s ease}.cpt-submit .cpt-spinner{width:16px;height:16px;border-color:color-mix(in srgb,currentColor 28%,transparent);border-top-color:currentColor}.cpt-submit:hover:not(:disabled){filter:brightness(.94)}.cpt-submit:active:not(:disabled){transform:translateY(1px)}.cpt-submit:focus-visible,.cpt-icon-button:focus-visible{outline:2px solid var(--cpt-focus);outline-offset:2px}.cpt-submit:disabled{cursor:default;opacity:.62}.cpt-footer{position:relative;display:flex;align-items:center;justify-content:space-between;padding:8px 12px;border-top:1px solid var(--cpt-border)}.cpt-toolbar{display:flex;gap:3px}.cpt-icon-button{display:grid;width:34px;height:34px;padding:0;place-items:center;border:0;border-radius:6px;background:transparent;color:var(--cpt-muted);cursor:pointer;transition:background .12s ease,color .12s ease}.cpt-icon-button:hover:not(:disabled){background:color-mix(in srgb,var(--cpt-text) 7%,transparent);color:var(--cpt-text)}.cpt-icon-button:disabled{cursor:default;opacity:.38}.cpt-icon-button svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.cpt-brand{padding-right:3px;font-size:12px;font-weight:700;color:var(--cpt-muted)}.cpt-tooltip-wrap{position:relative}.cpt-tooltip{position:absolute;left:0;bottom:calc(100% + 9px);width:max-content;max-width:min(220px,calc(100vw - 72px));padding:7px 9px;border-radius:5px;background:var(--cpt-tooltip-bg);color:var(--cpt-tooltip-text);font-size:12px;font-weight:400;line-height:18px;white-space:normal;opacity:0;visibility:hidden;pointer-events:none;transform:translateY(3px);transition:opacity .12s ease,transform .12s ease,visibility .12s ease}.cpt-tooltip-wrap:hover .cpt-tooltip,.cpt-tooltip-wrap:focus-within .cpt-tooltip{opacity:1;visibility:visible;transform:none}@keyframes cpt-spin{to{transform:rotate(360deg)}}@keyframes cpt-overlay-in{from{opacity:0}to{opacity:1}}@keyframes cpt-overlay-out{from{opacity:1}to{opacity:0}}@keyframes cpt-dialog-in{from{opacity:0;transform:translateY(8px) scale(.985)}to{opacity:1;transform:none}}@keyframes cpt-dialog-out{from{opacity:1;transform:none}to{opacity:0;transform:translateY(5px) scale(.99)}}@media (max-width:380px){.cpt-overlay{padding:10px}.cpt-modal{width:calc(100vw - 20px)}.cpt-header{padding:15px 16px 11px}.cpt-body{padding:0 16px 14px}.cpt-answer-row{display:grid}.cpt-submit{width:100%}.cpt-tooltip{left:50%;transform:translate(-50%,3px);max-width:min(220px,calc(100vw - 52px))}.cpt-tooltip-wrap:hover .cpt-tooltip,.cpt-tooltip-wrap:focus-within .cpt-tooltip{transform:translateX(-50%)}}@media (prefers-reduced-motion:reduce){.cpt-spinner{animation:none}.cpt-overlay,.cpt-modal,.cpt-overlay--leaving,.cpt-overlay--leaving .cpt-modal{animation:none}.cpt-success,.cpt-answer,.cpt-submit,.cpt-icon-button,.cpt-tooltip{transition:none}}';

let dialogSequence = 0;

function createIcon(paths: readonly string[]): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  for (const data of paths) {
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', data);
    svg.append(path);
  }
  return svg;
}

function createIconButton(label: string, paths: readonly string[]): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'cpt-icon-button';
  button.setAttribute('aria-label', label);
  button.append(createIcon(paths));
  return button;
}

export function renderCharacter(container: HTMLElement | ShadowRoot, options: CharacterRendererOptions): CharacterRendererHandle {
  const style = document.createElement('style');
  style.textContent = `${HOST_RESET}${COMPONENT_STYLES}${BRAND_STYLES}${CHARACTER_STYLES}`;
  const overlay = document.createElement('div');
  overlay.className = 'cpt-overlay';
  const dialog = document.createElement('section');
  dialog.className = 'cpt-modal';
  dialog.setAttribute('role', 'dialog');
  dialog.setAttribute('aria-modal', 'true');
  const titleId = `cpt-character-title-${++dialogSequence}`;
  dialog.setAttribute('aria-labelledby', titleId);
  const header = document.createElement('header');
  header.className = 'cpt-header';
  const title = document.createElement('h2');
  title.id = titleId;
  title.className = 'cpt-title';
  title.textContent = '安全验证';
  const instruction = document.createElement('p');
  instruction.className = 'cpt-instruction';
  header.append(title, instruction);
  const body = document.createElement('div');
  body.className = 'cpt-body';
  const mediaStage = document.createElement('div');
  mediaStage.className = 'cpt-media-stage';
  const success = document.createElement('div');
  success.className = 'cpt-success';
  success.setAttribute('role', 'status');
  success.setAttribute('aria-live', 'polite');
  const successIcon = document.createElement('span');
  successIcon.className = 'cpt-success-icon';
  successIcon.textContent = '✓';
  const successText = document.createElement('span');
  successText.textContent = '验证通过';
  success.append(successIcon, successText);
  const answerRow = document.createElement('div');
  answerRow.className = 'cpt-answer-row';
  const input = document.createElement('input');
  input.className = 'cpt-answer';
  input.type = 'text';
  input.inputMode = 'text';
  input.autocomplete = 'off';
  input.maxLength = 5;
  input.placeholder = '输入 5 位字符';
  input.setAttribute('aria-label', '字符答案');
  const submit = document.createElement('button');
  submit.type = 'button';
  submit.className = 'cpt-submit';
  submit.textContent = '提交';
  submit.disabled = true;
  answerRow.append(input, submit);
  body.append(mediaStage, answerRow);
  const footer = document.createElement('footer');
  footer.className = 'cpt-footer';
  const toolbar = document.createElement('div');
  toolbar.className = 'cpt-toolbar';
  const close = createIconButton('关闭挑战', ['M6 6l12 12', 'M18 6 6 18']);
  const refresh = createIconButton('刷新挑战', ['M20 11a8 8 0 1 0-2.3 5.7', 'M20 4v7h-7']);
  const helpWrap = document.createElement('span');
  helpWrap.className = 'cpt-tooltip-wrap';
  const help = createIconButton('帮助', ['M9.5 9a2.7 2.7 0 1 1 4.2 2.2c-1 .7-1.7 1.2-1.7 2.3', 'M12 17h.01', 'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z']);
  const tooltip = document.createElement('span');
  const tooltipId = `cpt-character-help-${dialogSequence}`;
  tooltip.id = tooltipId;
  tooltip.className = 'cpt-tooltip';
  tooltip.setAttribute('role', 'tooltip');
  help.setAttribute('aria-describedby', tooltipId);
  helpWrap.append(help, tooltip);
  toolbar.append(close, refresh, helpWrap);
  footer.append(toolbar, createBrandLockup('footer'));
  dialog.append(header, body, footer);
  overlay.append(dialog);
  container.append(style, overlay);

  let player: GhostStreamPlayer | undefined;
  let destroyed = false;
  let submitting = false;
  let refreshing = false;
  let leaving = false;
  let replacementGeneration = 0;
  let closeTimer: ReturnType<typeof setTimeout> | undefined;
  let mediaController: AbortController | undefined;
  let powOverlay: PowOverlayHandle | undefined;
  let powPending = false;
  let powReveal: PowRevealResult | undefined;

  const mountPowOverlay = (image: HTMLImageElement, challenge: CharacterChallenge & { kind: 'decoy' }): void => {
    powOverlay?.destroy();
    powOverlay = undefined;
    powPending = true;
    powReveal = undefined;
    // 原图不再整体展示：由 div 网格切分显示（占位仅用于保持容器尺寸）
    image.style.opacity = '0';
    powOverlay = renderPowOverlay(mediaStage, {
      imageUrl: image.src,
      pow: challenge.pow,
      onRevealed: (result) => {
        powReveal = result;
        powPending = false;
        onInput();
      },
      onError: (error) => {
        if (!destroyed) options.onMediaError?.(error);
      },
    });
    onInput();
  };

  const createMediaLoading = (): HTMLDivElement => {
    const mask = document.createElement('div');
    mask.className = 'cpt-media-refresh';
    const spinner = document.createElement('span');
    spinner.className = 'cpt-spinner';
    spinner.setAttribute('aria-hidden', 'true');
    mask.append(spinner);
    return mask;
  };

  const setSubmitContent = (busy: boolean): void => {
    submit.replaceChildren();
    if (busy) submit.append(createMediaLoading().querySelector('.cpt-spinner')!);
    submit.append(document.createTextNode(busy ? '验证中' : '提交'));
  };

  const updateGuidance = (challenge: CharacterChallenge): void => {
    instruction.textContent = challenge.prompt;
    tooltip.textContent = challenge.kind === 'decoy'
      ? '眯起眼睛观察，忽略轮廓字符，输入更实心的 5 位大写字母或数字。'
      : '输入媒体中显示的 5 位字母或数字。';
  };

  const destroyPlayer = (): void => {
    mediaController?.abort();
    mediaController = undefined;
    player?.destroy();
    player = undefined;
  };

  const replaceMedia = async (challenge: CharacterChallenge): Promise<void> => {
    destroyPlayer();
    mediaStage.replaceChildren();
    mediaStage.classList.remove('cpt-media-stage--decoy', 'cpt-media-stage--ghost');
    mediaStage.classList.add(`cpt-media-stage--${challenge.kind}`);
    updateGuidance(challenge);
    if (challenge.kind === 'decoy') {
      if (!challenge.image.startsWith('data:image/png;base64,')) throw new Error('CORPTCHA_INVALID_DECOY_IMAGE');
      const image = document.createElement('img');
      image.src = challenge.image;
      image.alt = challenge.prompt;
      image.hidden = true;
      const mask = createMediaLoading();
      mediaStage.append(image, mask);
      if (challenge.pow) mountPowOverlay(image, challenge);
      return new Promise<void>((resolve, reject) => {
        const finish = (error?: Error): void => {
          mask.remove();
          if (destroyed) {
            resolve();
            return;
          }
          if (error) {
            image.remove();
            reject(error);
            return;
          }
          image.hidden = false;
          resolve();
        };
        image.addEventListener('load', () => finish(), { once: true });
        image.addEventListener('error', () => finish(new Error('CORPTCHA_INVALID_DECOY_IMAGE')), { once: true });
      });
    }
    if (challenge.mediaType !== 'application/vnd.ghost-font-stream') throw new Error('CORPTCHA_INVALID_GHOST_STREAM');
    const mask = createMediaLoading();
    mediaStage.append(mask);
    const canvas = document.createElement('canvas');
    canvas.setAttribute('role', 'img');
    canvas.setAttribute('aria-label', challenge.prompt);
    const nextPlayer = new GhostStreamPlayer(canvas);
    const controller = new AbortController();
    mediaController = controller;
    player = nextPlayer;
    mediaStage.prepend(canvas);
    try {
      await nextPlayer.playResponse(await challenge.loadMedia(controller.signal));
    } catch (error) {
      nextPlayer.destroy();
      if (player === nextPlayer) player = undefined;
      throw error;
    }
    mask.remove();
  };

  const prepareMedia = async (challenge: CharacterChallenge): Promise<{ element: HTMLImageElement | HTMLCanvasElement; player?: GhostStreamPlayer }> => {
    if (challenge.kind === 'decoy') {
      if (!challenge.image.startsWith('data:image/png;base64,')) throw new Error('CORPTCHA_INVALID_DECOY_IMAGE');
      const image = document.createElement('img');
      image.src = challenge.image;
      image.alt = challenge.prompt;
      image.hidden = true;
      mediaStage.append(image);
      await new Promise<void>((resolve, reject) => {
        image.addEventListener('load', () => resolve(), { once: true });
        image.addEventListener('error', () => reject(new Error('CORPTCHA_INVALID_DECOY_IMAGE')), { once: true });
      }).catch((error) => {
        image.remove();
        throw error;
      });
      image.hidden = false;
      return { element: image };
    }
    if (challenge.mediaType !== 'application/vnd.ghost-font-stream') throw new Error('CORPTCHA_INVALID_GHOST_STREAM');
    const canvas = document.createElement('canvas');
    canvas.setAttribute('role', 'img');
    canvas.setAttribute('aria-label', challenge.prompt);
    const nextPlayer = new GhostStreamPlayer(canvas);
    const controller = new AbortController();
    try {
      await nextPlayer.playResponse(await challenge.loadMedia(controller.signal));
      return { element: canvas, player: nextPlayer };
    } catch (error) {
      nextPlayer.destroy();
      throw error;
    }
  };

  const focusable = (): HTMLElement[] => [...dialog.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled)')];
  const cleanup = (): void => {
    if (destroyed) return;
    destroyed = true;
    if (closeTimer !== undefined) clearTimeout(closeTimer);
    destroyPlayer();
    powOverlay?.destroy();
    powOverlay = undefined;
    overlay.removeEventListener('keydown', onKeyDown);
    overlay.removeEventListener('click', onOverlayClick);
    input.removeEventListener('input', onInput);
    submit.removeEventListener('click', onSubmit);
    close.removeEventListener('click', onClose);
    refresh.removeEventListener('click', onRefresh);
    style.remove();
    overlay.remove();
  };
  const closeDialog = (): void => {
    if (destroyed || submitting || refreshing || leaving) return;
    leaving = true;
    destroyPlayer();
    overlay.classList.add('cpt-overlay--leaving');
    closeTimer = setTimeout(() => {
      cleanup();
      options.onClose();
      options.restoreFocus.focus();
    }, 160);
  };
  const refreshDialog = (): void => {
    if (destroyed || submitting || refreshing || leaving) return;
    options.onRefresh();
  };
  const submitAnswer = (): void => {
    if (submitting || powPending) return;
    const answer = input.value.toUpperCase();
    if (/^[A-Z0-9]{5}$/.test(answer)) options.onSubmit(answer, powReveal);
  };
  const onInput = (): void => {
    input.value = input.value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 5);
    submit.disabled = submitting || refreshing || powPending || !/^[A-Z0-9]{5}$/.test(input.value);
  };
  const onSubmit = (): void => submitAnswer();
  const onClose = (): void => closeDialog();
  const onRefresh = (): void => refreshDialog();
  const onOverlayClick = (event: MouseEvent): void => {
    if (event.target === overlay) closeDialog();
  };
  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key === 'Escape') {
      event.preventDefault();
      if (!submitting && !refreshing) closeDialog();
      return;
    }
    if (event.key === 'Enter' && event.target === input) {
      event.preventDefault();
      submitAnswer();
      return;
    }
    if (event.key !== 'Tab') return;
    const controls = focusable();
    const first = controls[0];
    const last = controls.at(-1);
    if (!first || !last) {
      event.preventDefault();
      dialog.focus();
      return;
    }
    if ((!event.shiftKey && document.activeElement === last) || (event.shiftKey && document.activeElement === first)) {
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
    }
  };

  overlay.addEventListener('keydown', onKeyDown);
  overlay.addEventListener('click', onOverlayClick);
  input.addEventListener('input', onInput);
  submit.addEventListener('click', onSubmit);
  close.addEventListener('click', onClose);
  refresh.addEventListener('click', onRefresh);

  let ready: Promise<void>;
  try {
    ready = replaceMedia(options.challenge);
    mediaStage.append(success);
  } catch (error) {
    cleanup();
    throw error;
  }
  void ready.catch((error: unknown) => {
    if (!destroyed) options.onMediaError?.(error instanceof Error ? error : new Error('CORPTCHA_MEDIA_PREPARATION_FAILED'));
  });
  input.focus();

  return {
    ready,
    setSubmitting(value) {
      if (destroyed) return;
      submitting = value;
      input.disabled = value;
      for (const button of dialog.querySelectorAll('button')) button.disabled = value;
      submit.disabled = value || powPending || !/^[A-Z0-9]{5}$/.test(input.value);
      setSubmitContent(value);
      dialog.setAttribute('aria-busy', String(value));
    },
    setRefreshing(value) {
      if (destroyed) return;
      refreshing = value;
      close.disabled = value;
      refresh.disabled = value;
      input.disabled = value || submitting;
      submit.disabled = value || submitting || powPending || !/^[A-Z0-9]{5}$/.test(input.value);
      dialog.setAttribute('aria-busy', String(value || submitting));
      mediaStage.querySelector('.cpt-media-refresh')?.remove();
      if (value) mediaStage.append(createMediaLoading());
    },
    showSuccess() {
      if (destroyed) return;
      submitting = true;
      dialog.classList.add('cpt-modal--success');
      dialog.setAttribute('aria-busy', 'false');
    },
    startLeaving() {
      if (destroyed) return;
      leaving = true;
      destroyPlayer();
      overlay.classList.add('cpt-overlay--leaving');
    },
    async replace(challenge) {
      if (destroyed) return;
      const generation = ++replacementGeneration;
      const prepared = await prepareMedia(challenge);
      if (destroyed || generation !== replacementGeneration) {
        prepared.player?.destroy();
        return;
      }
      dialog.classList.remove('cpt-modal--success');
      destroyPlayer();
      player = prepared.player;
      powOverlay?.destroy();
      powOverlay = undefined;
      powPending = false;
      powReveal = undefined;
      mediaStage.classList.remove('cpt-media-stage--decoy', 'cpt-media-stage--ghost');
      mediaStage.classList.add(`cpt-media-stage--${challenge.kind}`);
      updateGuidance(challenge);
      mediaStage.replaceChildren(prepared.element, success);
      if (challenge.kind === 'decoy' && challenge.pow) mountPowOverlay(prepared.element as HTMLImageElement, challenge);
      input.value = '';
      submit.disabled = true;
      input.focus();
    },
    focus: () => { if (!destroyed) input.focus(); },
    destroy: cleanup,
  };
}
