import { BRAND_STYLES, createBrandLockup } from '../brand.js';
import { clamp01 } from '../coordinates.js';
import { prepareImages } from '../media.js';
import { PointerTelemetryCollector, type PointerDrag } from '../pointer-telemetry.js';
import { renderPowOverlay, type PowOverlayHandle, type PowRevealResult } from '../pow-overlay.js';
import type { PowParameters } from '../pow.js';
import { COMPONENT_STYLES, HOST_RESET, SPATIAL_STYLES, SUCCESS_FEEDBACK_STYLES } from '../styles.js';

export interface PuzzlePieceData {
  id: string;
  image: string;
  width: number;
  height: number;
}

export interface PuzzleChallengeData {
  schemaVersion: 1;
  interactionNonce: string;
  backgroundImage: string;
  imageWidth: number;
  imageHeight: number;
  pieces: readonly [PuzzlePieceData, PuzzlePieceData, PuzzlePieceData];
  pow: PowParameters;
}

export interface PuzzlePlacement {
  id: string;
  x: number;
  y: number;
}

export interface PuzzleResponse {
  schemaVersion: 1;
  interactionNonce: string;
  placements: readonly PuzzlePlacement[];
  powNonce: number;
}

export type PuzzleTelemetry = { schemaVersion: 1; mode: 'pointer'; drags: readonly (PointerDrag & { pieceId: string })[]; powActualMs: number };

export interface PuzzleRendererOptions {
  data: PuzzleChallengeData;
  restoreFocus: HTMLElement;
  onSubmit(response: PuzzleResponse, telemetry: PuzzleTelemetry): void;
  onRefresh(): void;
  onClose(): void;
  onMediaError?(error: Error): void;
}

export interface PuzzleRendererHandle {
  readonly ready: Promise<void>;
  setBusy(busy: boolean): void;
  setRefreshing(refreshing: boolean): void;
  lock(): void;
  focus(): void;
  destroy(): void;
}

interface PieceState {
  data: PuzzlePieceData;
  button: HTMLButtonElement;
  image: HTMLImageElement;
  x: number;
  y: number;
  startX: number;
  startY: number;
  grabX: number;
  grabY: number;
  collector: PointerTelemetryCollector | undefined;
  drag?: PointerDrag & { pieceId: string };
  placed: boolean;
}

const STYLES = '.cpt-puzzle{display:grid;gap:10px}.cpt-puzzle-stage{position:relative;width:100%;overflow:hidden;border:1px solid var(--cpt-border,#d5d9e2);border-radius:8px;background:var(--cpt-stage,#f1f3f6)}.cpt-puzzle-background{width:100%;height:100%;object-fit:contain}.cpt-puzzle-piece{position:absolute;z-index:1;display:grid;min-width:44px;min-height:44px;padding:0;place-items:center;border:0;background:transparent;touch-action:none;cursor:grab;transition:filter .12s ease,scale .12s ease}.cpt-puzzle-piece[data-picked="true"]{cursor:grabbing;scale:1.04;filter:drop-shadow(0 7px 6px rgba(15,23,42,.28))}.cpt-puzzle-piece[data-snapped="true"]{animation:cpt-puzzle-snap .18s ease-out}.cpt-puzzle-piece img{width:100%;height:100%;object-fit:contain;pointer-events:none}.cpt-puzzle-actions{display:flex;justify-content:flex-end;margin-top:11px}.cpt-puzzle-confirm{display:inline-flex;min-width:88px;min-height:42px;padding:0 15px;align-items:center;justify-content:center;gap:7px;border:1px solid var(--cpt-accent);border-radius:6px;background:var(--cpt-accent);color:var(--cpt-button-text);font-weight:650;cursor:pointer}.cpt-puzzle-confirm:disabled{cursor:default;opacity:.62}.cpt-instruction{margin:3px 0 0;color:var(--cpt-muted);font-size:13px;line-height:19px}.cpt-puzzle[aria-busy="true"]{opacity:.65}@keyframes cpt-puzzle-snap{50%{scale:1.035}}@media (prefers-reduced-motion:reduce){.cpt-puzzle-piece{transition:none}.cpt-puzzle-piece[data-picked="true"]{scale:none}.cpt-puzzle-piece[data-snapped="true"]{animation:none}}';

function rounded(value: number): number {
  return Number(clamp01(value).toFixed(4));
}

function iconButton(label: string, paths: readonly string[]): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'cpt-icon-button';
  button.setAttribute('aria-label', label);
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  for (const value of paths) {
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', value);
    svg.append(path);
  }
  button.append(svg);
  return button;
}

let dialogSequence = 0;

export function renderPuzzle(container: HTMLElement | ShadowRoot, options: PuzzleRendererOptions): PuzzleRendererHandle {
  const style = document.createElement('style');
  style.textContent = `${HOST_RESET}${COMPONENT_STYLES}${BRAND_STYLES}${SPATIAL_STYLES}${SUCCESS_FEEDBACK_STYLES}${STYLES}`;
  const overlay = document.createElement('div');
  overlay.className = 'cpt-overlay';
  const dialog = document.createElement('section');
  dialog.className = 'cpt-modal';
  dialog.setAttribute('role', 'dialog');
  dialog.setAttribute('aria-modal', 'true');
  const title = document.createElement('h2');
  title.id = `cpt-puzzle-title-${++dialogSequence}`;
  title.className = 'cpt-title';
  title.textContent = '安全验证';
  dialog.setAttribute('aria-labelledby', title.id);
  const header = document.createElement('header');
  header.className = 'cpt-header';
  const instruction = document.createElement('p');
  instruction.className = 'cpt-instruction';
  instruction.textContent = '将三块拼图碎片拖动到正确位置';
  header.append(title, instruction);
  const body = document.createElement('div');
  body.className = 'cpt-body';
  const root = document.createElement('section');
  root.className = 'cpt-puzzle';
  const stage = document.createElement('div');
  stage.className = 'cpt-puzzle-stage';
  stage.style.aspectRatio = `${options.data.imageWidth} / ${options.data.imageHeight}`;
  const actions = document.createElement('div');
  actions.className = 'cpt-puzzle-actions';
  const confirm = document.createElement('button');
  confirm.type = 'button';
  confirm.className = 'cpt-puzzle-confirm';
  confirm.textContent = '确认';
  confirm.disabled = true;
  actions.append(confirm);
  root.append(stage, actions);
  body.append(root);
  const footer = document.createElement('footer');
  footer.className = 'cpt-footer';
  const toolbar = document.createElement('div');
  toolbar.className = 'cpt-toolbar';
  const close = iconButton('关闭挑战', ['M6 6l12 12', 'M18 6 6 18']);
  const refresh = iconButton('刷新挑战', ['M20 11a8 8 0 1 0-2.3 5.7', 'M20 4v7h-7']);
  toolbar.append(close, refresh);
  footer.append(toolbar, createBrandLockup('footer'));
  dialog.append(header, body, footer);
  overlay.append(dialog);
  container.append(style, overlay);

  let destroyed = false;
  let locked = false;
  let busy = false;
  let refreshing = false;
  let leaving = false;
  let closeTimer: ReturnType<typeof setTimeout> | undefined;
  let powOverlay: PowOverlayHandle | undefined;
  let powReveal: PowRevealResult | undefined;
  const preparation = prepareImages([options.data.backgroundImage, ...options.data.pieces.map((piece) => piece.image)]);
  const background = preparation.images[0]!;
  background.className = 'cpt-puzzle-background';
  background.alt = '';
  background.hidden = true;
  stage.append(background);

  const states: PieceState[] = options.data.pieces.map((pieceData, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'cpt-puzzle-piece';
    button.dataset.pieceId = pieceData.id;
    button.setAttribute('aria-label', `移动拼图块 ${index + 1}`);
    button.style.minWidth = '44px';
    button.style.minHeight = '44px';
    const image = preparation.images[index + 1]!;
    image.alt = '';
    image.hidden = true;
    button.append(image);
    stage.append(button);
    return {
      data: pieceData,
      button,
      image,
      x: 0.1 + index * 0.35,
      y: 0.82,
      startX: 0,
      startY: 0,
      grabX: 0,
      grabY: 0,
      collector: undefined,
      placed: false,
    };
  });

  const pieceCss = (state: PieceState): { width: number; height: number } => {
    const rect = stage.getBoundingClientRect();
    return { width: rect.width * state.data.width / options.data.imageWidth, height: rect.height * state.data.height / options.data.imageHeight };
  };
  const renderState = (state: PieceState): void => {
    state.button.style.width = `${state.data.width / options.data.imageWidth * 100}%`;
    state.button.style.height = `${state.data.height / options.data.imageHeight * 100}%`;
    state.button.style.left = `${state.x * 100}%`;
    state.button.style.top = `${state.y * 100}%`;
    state.button.style.transform = `translate(${-state.x * 100}% ,${-state.y * 100}%)`;
  };
  states.forEach(renderState);
  const disabled = (): boolean => destroyed || locked || busy || refreshing || !powReveal;
  const update = (): void => {
    for (const state of states) state.button.disabled = disabled();
    close.disabled = disabled();
    refresh.disabled = disabled();
    confirm.disabled = disabled() || !states.every((state) => state.placed);
    root.setAttribute('aria-busy', String(busy || refreshing));
    dialog.setAttribute('aria-busy', String(busy || refreshing));
  };
  const abortAll = (): void => {
    for (const state of states) {
      state.collector?.abort();
      state.collector = undefined;
      state.button.dataset.picked = 'false';
      state.button.style.cursor = 'grab';
    }
  };
  const submit = (): void => {
    if (disabled() || !states.every((state) => state.placed)) return;
    if (!states.every((state) => state.drag && state.drag.events.length >= 4)) return;
    const response: PuzzleResponse = {
      schemaVersion: 1,
      interactionNonce: options.data.interactionNonce,
      placements: states.map((state) => ({ id: state.data.id, x: state.x, y: state.y })),
      powNonce: powReveal!.nonce,
    };
    options.onSubmit(response, { schemaVersion: 1, mode: 'pointer', drags: states.map((state) => state.drag!), powActualMs: powReveal!.actualMs });
  };
  const bind = (state: PieceState): void => {
    const down = (event: PointerEvent): void => {
      if (disabled()) return;
      state.startX = state.x;
      state.startY = state.y;
      const rect = stage.getBoundingClientRect();
      const size = pieceCss(state);
      state.grabX = event.clientX - rect.left - state.x * Math.max(1, rect.width - size.width);
      state.grabY = event.clientY - rect.top - state.y * Math.max(1, rect.height - size.height);
      const point = (pointer: PointerEvent): { x: number; y: number } => ({
        x: rounded((pointer.clientX - rect.left - state.grabX) / Math.max(1, rect.width - size.width)),
        y: rounded((pointer.clientY - rect.top - state.grabY) / Math.max(1, rect.height - size.height)),
      });
      const collector = new PointerTelemetryCollector({ target: state.button, rect: () => stage.getBoundingClientRect(), point });
      if (!collector.start(event)) return;
      state.collector = collector;
      state.button.dataset.picked = 'true';
      delete state.button.dataset.snapped;
      state.button.style.cursor = 'grabbing';
      states.forEach((entry) => { entry.button.style.zIndex = entry === state ? '2' : '1'; });
    };
    const move = (event: PointerEvent): void => {
      if (!state.collector?.move(event)) return;
      const rect = stage.getBoundingClientRect();
      const size = pieceCss(state);
      state.x = rounded((event.clientX - rect.left - state.grabX) / Math.max(1, rect.width - size.width));
      state.y = rounded((event.clientY - rect.top - state.grabY) / Math.max(1, rect.height - size.height));
      renderState(state);
    };
    const up = (event: PointerEvent): void => {
      const collector = state.collector;
      if (!collector) return;
      const rect = stage.getBoundingClientRect();
      const size = pieceCss(state);
      state.x = rounded((event.clientX - rect.left - state.grabX) / Math.max(1, rect.width - size.width));
      state.y = rounded((event.clientY - rect.top - state.grabY) / Math.max(1, rect.height - size.height));
      renderState(state);
      const drag = collector.finish(event, `drag-${state.data.id}`);
      state.collector = undefined;
      state.button.dataset.picked = 'false';
      state.button.style.cursor = 'grab';
      if (!drag) return;
      state.drag = { ...drag, pieceId: state.data.id };
      state.placed = true;
      state.button.dataset.snapped = 'true';
      update();
    };
    const cancel = (event: PointerEvent): void => {
      if (!state.collector) return;
      state.collector.cancel(event);
      state.collector = undefined;
      state.button.dataset.picked = 'false';
      state.button.style.cursor = 'grab';
      state.x = state.startX;
      state.y = state.startY;
      renderState(state);
    };
    state.button.addEventListener('pointerdown', down);
    state.button.addEventListener('pointermove', move);
    state.button.addEventListener('pointerup', up);
    state.button.addEventListener('pointercancel', cancel);
    Object.assign(state, { remove: () => {
      state.button.removeEventListener('pointerdown', down);
      state.button.removeEventListener('pointermove', move);
      state.button.removeEventListener('pointerup', up);
      state.button.removeEventListener('pointercancel', cancel);
    } });
  };
  states.forEach(bind);
  const blur = (): void => abortAll();
  const visibility = (): void => { if (document.visibilityState === 'hidden') abortAll(); };
  window.addEventListener('blur', blur);
  document.addEventListener('visibilitychange', visibility);

  const cleanup = (restore: boolean): void => {
    if (destroyed) return;
    destroyed = true;
    abortAll();
    if (closeTimer !== undefined) clearTimeout(closeTimer);
    powOverlay?.destroy();
    powOverlay = undefined;
    preparation.destroy();
    for (const state of states) (state as PieceState & { remove(): void }).remove();
    close.removeEventListener('click', onClose);
    refresh.removeEventListener('click', onRefresh);
    overlay.removeEventListener('keydown', onOverlayKeyDown);
    overlay.removeEventListener('click', onOverlayClick);
    window.removeEventListener('blur', blur);
    document.removeEventListener('visibilitychange', visibility);
    overlay.remove();
    style.remove();
    if (restore) options.restoreFocus.focus();
  };
  const closeDialog = (): void => {
    if (disabled() || leaving) return;
    leaving = true;
    overlay.classList.add('cpt-overlay--leaving');
    closeTimer = setTimeout(() => {
      cleanup(true);
      options.onClose();
    }, 160);
  };
  function onClose(): void { closeDialog(); }
  function onRefresh(): void { if (!disabled() && !leaving) options.onRefresh(); }
  function onConfirm(): void { if (!disabled() && !leaving) submit(); }
  function onOverlayKeyDown(event: KeyboardEvent): void {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    closeDialog();
  }
  function onOverlayClick(event: MouseEvent): void { if (event.target === overlay) closeDialog(); }
  close.addEventListener('click', onClose);
  refresh.addEventListener('click', onRefresh);
  confirm.addEventListener('click', onConfirm);
  overlay.addEventListener('keydown', onOverlayKeyDown);
  overlay.addEventListener('click', onOverlayClick);

  powOverlay = renderPowOverlay(stage, {
    imageUrl: options.data.backgroundImage,
    pow: options.data.pow,
    onRevealed: (result) => {
      powReveal = result;
      update();
    },
    onError: (error) => {
      if (!destroyed) options.onMediaError?.(error);
    },
  });
  update();

  const ready = preparation.ready.then(() => {
    if (destroyed) return;
    // 背景不再整体展示：由 div 网格切分显示
    background.style.opacity = '0';
    for (const state of states) state.image.hidden = false;
  });
  void ready.catch((error: unknown) => {
    if (!destroyed) options.onMediaError?.(error instanceof Error ? error : new Error('CORPTCHA_MEDIA_ERROR'));
  });

  return {
    ready,
    setBusy: (value) => { busy = value; update(); },
    setRefreshing: (value) => { refreshing = value; if (value) abortAll(); update(); },
    lock: () => { locked = true; abortAll(); update(); },
    focus: () => states[0]?.button.focus(),
    destroy: () => cleanup(true),
  };
}
