import { clamp01, type CoordinateRect } from './coordinates.js';

export type DragPointerType = 'mouse' | 'touch' | 'pen';
export type PointerPhase = 'down' | 'move' | 'up' | 'cancel';

export interface PointerTelemetryEvent {
  phase: PointerPhase;
  pointerId: number;
  pointerType: DragPointerType;
  x: number;
  y: number;
  dtMs: number;
}

export interface PointerDrag {
  id: string;
  events: readonly PointerTelemetryEvent[];
}

export interface PointerTelemetryOptions {
  target: Element;
  rect(): CoordinateRect;
  point?(event: PointerEvent): { x: number; y: number };
  now?: () => number;
}

export class PointerTelemetryCollector {
  private readonly events: PointerTelemetryEvent[] = [];
  private pointerId: number | undefined;
  private pointerType: DragPointerType | undefined;
  private startedAt = 0;
  private cancelled = false;

  constructor(private readonly options: PointerTelemetryOptions) {}

  get active(): boolean {
    return this.pointerId !== undefined && !this.cancelled;
  }

  start(event: PointerEvent): boolean {
    if (this.active || !this.isPointerType(event.pointerType)) return false;
    this.pointerId = event.pointerId;
    this.pointerType = event.pointerType;
    this.startedAt = this.now();
    this.cancelled = false;
    this.events.splice(0);
    this.add('down', event);
    this.options.target.setPointerCapture(event.pointerId);
    return true;
  }

  move(event: PointerEvent): boolean {
    if (!this.matches(event)) return false;
    this.add('move', event);
    this.limitEvents();
    return true;
  }

  finish(event: PointerEvent, id: string): PointerDrag | undefined {
    if (!this.matches(event)) return undefined;
    this.add('up', event);
    this.limitEvents();
    const events = this.events.map((entry) => ({ ...entry }));
    this.release();
    return { id, events };
  }

  cancel(event: PointerEvent): void {
    if (!this.matches(event)) return;
    this.add('cancel', event);
    this.cancelled = true;
    this.release();
  }

  abort(_reason?: string): void {
    if (this.pointerId === undefined) return;
    this.cancelled = true;
    this.release();
  }

  private add(phase: PointerPhase, event: PointerEvent): void {
    const point = this.options.point?.(event);
    const rect = point ? undefined : this.options.rect();
    const x = clamp01(point?.x ?? (rect!.width > 0 ? (event.clientX - rect!.left) / rect!.width : 0));
    const y = clamp01(point?.y ?? (rect!.height > 0 ? (event.clientY - rect!.top) / rect!.height : 0));
    const elapsed = Math.max(0, Math.round(this.now() - this.startedAt));
    const previous = this.events.at(-1)?.dtMs;
    this.events.push({
      phase,
      pointerId: event.pointerId,
      pointerType: this.pointerType!,
      x: Number(x.toFixed(4)),
      y: Number(y.toFixed(4)),
      dtMs: previous === undefined ? elapsed : Math.max(elapsed, previous + 1),
    });
  }

  private limitEvents(): void {
    while (this.events.length > 64) this.events.splice(1, 1);
  }

  private matches(event: PointerEvent): boolean {
    return this.active && event.pointerId === this.pointerId && event.pointerType === this.pointerType;
  }

  private release(): void {
    const pointerId = this.pointerId;
    this.pointerId = undefined;
    if (pointerId === undefined) return;
    if (this.options.target.hasPointerCapture(pointerId)) this.options.target.releasePointerCapture(pointerId);
  }

  private isPointerType(value: string): value is DragPointerType {
    return value === 'mouse' || value === 'touch' || value === 'pen';
  }

  private now(): number {
    return this.options.now?.() ?? performance.now();
  }
}
