import { WidgetError, type ChallengeIssueResult, type IssueResult } from './types.js';

export interface CorptchaOptions {
  apiBaseUrl: string;
  siteKey: string;
  purpose: string;
}

export interface SubmitChallengeResult {
  success: true;
  verificationToken: string;
}

type ResponseGuard<T> = (value: unknown) => value is T;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

function hasExactKeys(value: Record<string, unknown>, keys: string[]): boolean {
  const actual = Object.keys(value).sort();
  return actual.length === keys.length && actual.every((key, index) => key === [...keys].sort()[index]);
}

function isExpiresAt(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 20 && value.length <= 32 && !Number.isNaN(Date.parse(value));
}

function isSpatialData(value: unknown): boolean {
  return isRecord(value)
    && hasExactKeys(value, ['interactionNonce', 'image', 'width', 'height', 'pow'])
    && isNonEmptyString(value.interactionNonce)
    && typeof value.image === 'string'
    && value.image.startsWith('data:image/png;base64,')
    && value.width === 600
    && value.height === 375
    && isPowParameters(value.pow);
}

function isImage(value: unknown): value is string {
  return typeof value === 'string' && /^data:image\/png;base64,(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value);
}

function isDimension(value: unknown): value is number {
  return Number.isInteger(value) && Number(value) >= 1 && Number(value) <= 4096;
}

function isCoordinate(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 1;
}

function isNonce(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 16 && value.length <= 128;
}

function isPowParameters(value: unknown): boolean {
  if (!isRecord(value) || !isNonEmptyString(value.powSalt)) return false;
  const keys = Object.keys(value);
  // 除服务端必发字段外，仅允许可选的纯客户端调优字段 minShuffleMs
  if (keys.length > 6 || keys.some((key) => key !== 'powStart' && key !== 'powTarget' && key !== 'powSalt' && key !== 'gridCols' && key !== 'gridRows' && key !== 'minShuffleMs')) return false;
  if (!keys.includes('powStart') || !keys.includes('powTarget') || !keys.includes('powSalt') || !keys.includes('gridCols') || !keys.includes('gridRows')) return false;
  if ('minShuffleMs' in value && !(Number.isInteger(value.minShuffleMs) && Number(value.minShuffleMs) >= 0)) return false;
  return typeof value.powStart === 'number'
    && Number.isFinite(value.powStart)
    && Number(value.powStart) >= 0
    && typeof value.powTarget === 'string'
    && /^[0-9a-f]{64}$/.test(value.powTarget)
    && Number.isInteger(value.gridCols)
    && Number(value.gridCols) >= 2
    && Number(value.gridCols) <= 16
    && Number.isInteger(value.gridRows)
    && Number(value.gridRows) >= 2
    && Number(value.gridRows) <= 16;
}

function isSliderData(value: unknown): boolean {
  return isRecord(value)
    && hasExactKeys(value, ['schemaVersion', 'interactionNonce', 'backgroundImage', 'pieceImage', 'imageWidth', 'imageHeight', 'pieceWidth', 'pieceHeight', 'pieceY', 'trackStartX', 'pow'])
    && value.schemaVersion === 1
    && isNonce(value.interactionNonce)
    && isImage(value.backgroundImage)
    && isImage(value.pieceImage)
    && isDimension(value.imageWidth)
    && isDimension(value.imageHeight)
    && isDimension(value.pieceWidth)
    && isDimension(value.pieceHeight)
    && Number.isInteger(value.pieceY)
    && Number(value.pieceY) >= 0
    && Number(value.pieceY) <= Number(value.imageHeight) - Number(value.pieceHeight)
    && isCoordinate(value.trackStartX)
    && isPowParameters(value.pow);
}

function isPuzzleData(value: unknown): boolean {
  if (!isRecord(value)
    || !hasExactKeys(value, ['schemaVersion', 'interactionNonce', 'backgroundImage', 'imageWidth', 'imageHeight', 'pieces', 'pow'])
    || value.schemaVersion !== 1
    || !isNonce(value.interactionNonce)
    || !isImage(value.backgroundImage)
    || !isDimension(value.imageWidth)
    || !isDimension(value.imageHeight)
    || !isPowParameters(value.pow)
    || !Array.isArray(value.pieces)
    || value.pieces.length !== 3) return false;
  const ids = new Set<string>();
  for (const piece of value.pieces) {
    if (!isRecord(piece)
      || !hasExactKeys(piece, ['id', 'image', 'width', 'height'])
      || typeof piece.id !== 'string'
      || !/^[A-Za-z0-9_-]{1,64}$/.test(piece.id)
      || !isImage(piece.image)
      || !isDimension(piece.width)
      || !isDimension(piece.height)
      || ids.has(piece.id)) return false;
    ids.add(piece.id);
  }
  return true;
}

function isRotatePuzzleData(value: unknown): boolean {
  return isRecord(value)
    && hasExactKeys(value, ['schemaVersion', 'interactionNonce', 'fixedImage', 'rotatingImage', 'imageSize', 'rotatingPart', 'maxRotationDegrees', 'direction', 'pow'])
    && value.schemaVersion === 1
    && isNonce(value.interactionNonce)
    && isImage(value.fixedImage)
    && isImage(value.rotatingImage)
    && isDimension(value.imageSize)
    && (value.rotatingPart === 'ring' || value.rotatingPart === 'inner')
    && typeof value.maxRotationDegrees === 'number'
    && Number.isFinite(value.maxRotationDegrees)
    && value.maxRotationDegrees >= 145
    && value.maxRotationDegrees <= 360
    && (value.direction === -1 || value.direction === 1)
    && isPowParameters(value.pow);
}

function isChallengeIssueResult(value: unknown): value is ChallengeIssueResult {
  return isRecord(value)
    && hasExactKeys(value, ['outcome', 'challengeId', 'kind', 'expiresAt', 'data'])
    && value.outcome === 'challenge'
    && isNonEmptyString(value.challengeId)
    && ['click', 'drag_confirm', 'slider', 'puzzle', 'rotate_puzzle', 'decoy', 'ghost', 'spatial'].includes(String(value.kind))
    && isExpiresAt(value.expiresAt)
    && (value.kind === 'spatial' ? isSpatialData(value.data)
      : value.kind === 'slider' ? isSliderData(value.data)
      : value.kind === 'puzzle' ? isPuzzleData(value.data)
      : value.kind === 'rotate_puzzle' ? isRotatePuzzleData(value.data)
      : isRecord(value.data));
}

function isIssueResult(value: unknown): value is IssueResult {
  if (isChallengeIssueResult(value)) return true;
  return isRecord(value)
    && hasExactKeys(value, ['outcome', 'verificationToken', 'expiresAt'])
    && value.outcome === 'passed'
    && isNonEmptyString(value.verificationToken)
    && value.verificationToken.length >= 32
    && value.verificationToken.length <= 256
    && isExpiresAt(value.expiresAt);
}

function isSubmitChallengeResult(value: unknown): value is SubmitChallengeResult {
  return isRecord(value) && value.success === true && isNonEmptyString(value.verificationToken);
}

function trustedErrorPayload(value: unknown): { errorCode: string; message: string; requestId?: string } | undefined {
  if (!isRecord(value) || !isNonEmptyString(value.errorCode) || !isNonEmptyString(value.message)) return undefined;
  return {
    errorCode: value.errorCode,
    message: value.message,
    ...(isNonEmptyString(value.requestId) ? { requestId: value.requestId } : {}),
  };
}

export class CorptchaClient {
  constructor(private readonly options: CorptchaOptions, private readonly fetcher: typeof fetch = fetch) {}

  async issue(signals: unknown, signal?: AbortSignal): Promise<IssueResult> {
    return this.request('/v1/widget/challenges', { siteKey: this.options.siteKey, purpose: this.options.purpose, signals }, isIssueResult, signal);
  }

  async refresh(challengeId: string, signals: unknown, signal?: AbortSignal): Promise<ChallengeIssueResult> {
    return this.request(`/v1/widget/challenges/${encodeURIComponent(challengeId)}/refresh`, { signals }, isChallengeIssueResult, signal);
  }

  async submit(challengeId: string, response: Record<string, unknown>, telemetry: unknown, signal?: AbortSignal): Promise<SubmitChallengeResult> {
    return this.request(`/v1/widget/challenges/${encodeURIComponent(challengeId)}/submissions`, { response, telemetry }, isSubmitChallengeResult, signal);
  }

  async media(path: string, signal?: AbortSignal): Promise<Response> {
    if (!/^\/v1\/widget\/media\/[A-Za-z0-9_-]+$/.test(path)) throw new WidgetError('Corptcha returned an invalid media URL', { errorCode: 'CORPTCHA_INVALID_MEDIA_URL' });
    const base = this.options.apiBaseUrl.replace(/\/$/, '');
    const response = await this.fetcher(`${base}${path}`, signal ? { signal } : {});
    if (!response.ok) throw new WidgetError('Corptcha media request failed', { errorCode: 'CORPTCHA_MEDIA_REQUEST_FAILED', status: response.status });
    if (response.headers.get('content-type')?.split(';', 1)[0]?.trim().toLowerCase() !== 'application/vnd.ghost-font-stream') {
      await response.body?.cancel();
      throw new WidgetError('Corptcha returned invalid media', { errorCode: 'CORPTCHA_INVALID_MEDIA_RESPONSE', status: response.status });
    }
    return response;
  }

  private async request<T>(path: string, body: unknown, guard: ResponseGuard<T>, signal?: AbortSignal): Promise<T> {
    const base = this.options.apiBaseUrl.replace(/\/$/, '');
    const response = await this.fetcher(`${base}${path}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body),
      ...(signal ? { signal } : {}),
    });
    const contentType = response.headers?.get('content-type')?.toLowerCase() ?? 'application/json';
    const payload: unknown = contentType.includes('application/json')
      ? await response.json().catch(() => undefined)
      : undefined;
    if (!response.ok) {
      const error = trustedErrorPayload(payload);
      throw new WidgetError(error?.message ?? 'Corptcha request failed', {
        errorCode: error?.errorCode ?? 'CORPTCHA_REQUEST_FAILED',
        status: response.status,
        requestId: error?.requestId ?? response.headers?.get('x-request-id') ?? undefined,
      });
    }
    if (!guard(payload)) {
      throw new WidgetError('Corptcha returned an invalid response', {
        errorCode: 'CORPTCHA_INVALID_RESPONSE',
        status: response.status,
        requestId: response.headers?.get('x-request-id') ?? undefined,
      });
    }
    return payload;
  }
}
