import { BRAND_STYLES, createBrandLockup } from '../brand.js';
import { COMPONENT_STYLES, HOST_RESET } from '../styles.js';
import type { SuccessFeedback } from '../success-feedback.js';
import type { WidgetState, WidgetStateName } from '../types.js';

export interface CompactRendererOptions {
  initialState: WidgetState;
  onAction(event: MouseEvent): void;
}

export interface CompactRendererHandle {
  update(state: WidgetState): void;
  showSuccessFeedback(feedback: SuccessFeedback): void;
  setLocked(locked: boolean): void;
  focus(): void;
  destroy(): void;
}

interface CompactPresentation {
  primary: string;
  secondary: string;
  actionLabel: string;
  icon: 'empty' | 'progress' | 'success' | 'error' | 'expired';
  disabled: boolean;
}

const PRESENTATIONS: Readonly<Record<WidgetStateName, Omit<CompactPresentation, 'secondary'>>> = {
  idle: { primary: '开始验证', actionLabel: '开始验证', icon: 'empty', disabled: false },
  analyzing: { primary: '正在分析', actionLabel: '正在分析', icon: 'progress', disabled: true },
  ready: { primary: '完成验证', actionLabel: '完成验证', icon: 'empty', disabled: false },
  submitting: { primary: '正在验证', actionLabel: '正在验证', icon: 'progress', disabled: true },
  success: { primary: '验证通过', actionLabel: '验证通过', icon: 'success', disabled: true },
  error: { primary: '验证失败', actionLabel: '重试验证', icon: 'error', disabled: false },
  expired: { primary: '验证已过期', actionLabel: '重新验证', icon: 'expired', disabled: false },
  destroyed: { primary: '验证不可用', actionLabel: '验证不可用', icon: 'error', disabled: true },
};

const SECONDARY: Readonly<Record<WidgetStateName, string>> = {
  idle: '验证您是真实用户',
  analyzing: '请稍候',
  ready: '需要您的操作',
  submitting: '请勿关闭页面',
  success: '已安全验证',
  error: '请重试',
  expired: '请重新验证',
  destroyed: '组件已销毁',
};

const COMPACT_STYLES = '.cpt-compact{display:flex;align-items:center;width:100%;height:64px;min-width:0;padding:0 14px;border:1px solid var(--cpt-border);border-radius:var(--cpt-radius,8px);background:var(--cpt-surface);color:var(--cpt-text);text-align:left;cursor:pointer;transition:border-color .16s ease,box-shadow .16s ease}.cpt-compact:not(:disabled):hover{border-color:var(--cpt-hover)}.cpt-compact:focus-visible{outline:2px solid var(--cpt-focus)}.cpt-compact:disabled{cursor:default;opacity:1}.cpt-compact[data-success-pulse="true"]{animation:cpt-success-pulse .42s ease-out}.cpt-status-icon{display:grid;flex:0 0 32px;width:32px;height:32px;margin-right:11px;place-items:center;color:var(--cpt-accent)}.cpt-status-icon--checkbox{width:28px;height:28px;flex-basis:28px;border:2px solid currentColor;border-radius:5px}.cpt-status-icon[data-tone="success"]{color:var(--cpt-success)}.cpt-status-icon[data-tone="danger"]{color:var(--cpt-danger)}.cpt-status-icon svg{width:26px;height:26px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.cpt-status-icon--checkbox svg{width:20px;height:20px}.cpt-spinner{width:24px;height:24px;border:2px solid color-mix(in srgb,currentColor 22%,transparent);border-top-color:currentColor;border-radius:50%;animation:cpt-spin .8s linear infinite}.cpt-status-icon--checkbox .cpt-spinner{width:16px;height:16px}.cpt-copy{min-width:0;flex:1}.cpt-primary,.cpt-secondary{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cpt-primary{font-size:14px;font-weight:600;line-height:20px}.cpt-secondary{font-size:12px;line-height:18px;color:var(--cpt-muted)}@keyframes cpt-spin{to{transform:rotate(360deg)}}@keyframes cpt-success-pulse{50%{border-color:var(--cpt-success);box-shadow:0 0 0 3px color-mix(in srgb,var(--cpt-success) 12%,transparent)}}@media (prefers-reduced-motion:reduce){.cpt-compact[data-success-pulse="true"]{animation:none}}';

function createIcon(name: 'success' | 'error' | 'expired'): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  svg.dataset.icon = name;
  const paths: Readonly<Record<typeof name, readonly string[]>> = {
    success: ['M20 6 9 17l-5-5'],
    error: ['M12 8v5', 'M12 17h.01', 'M10.3 3.8 2.6 18a2 2 0 0 0 1.8 3h15.2a2 2 0 0 0 1.8-3L13.7 3.8a2 2 0 0 0-3.4 0Z'],
    expired: ['M12 8v4l3 2', 'M3.1 12a9 9 0 1 0 2.6-6.3L3 8', 'M3 3v5h5'],
  };
  for (const data of paths[name]) {
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', data);
    svg.append(path);
  }
  return svg;
}

function presentationFor(state: WidgetState): CompactPresentation {
  const base = PRESENTATIONS[state.name];
  return {
    ...base,
    secondary: state.name === 'error' ? state.error.message : SECONDARY[state.name],
  };
}

export function renderCompact(container: HTMLElement | ShadowRoot, options: CompactRendererOptions): CompactRendererHandle {
  const style = document.createElement('style');
  style.textContent = `${HOST_RESET}${COMPONENT_STYLES}${BRAND_STYLES}${COMPACT_STYLES}`;
  const control = document.createElement('button');
  control.type = 'button';
  control.className = 'cpt-compact';
  const icon = document.createElement('span');
  icon.className = 'cpt-status-icon';
  const status = document.createElement('span');
  status.className = 'cpt-copy';
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  status.setAttribute('aria-atomic', 'true');
  const primary = document.createElement('span');
  primary.className = 'cpt-primary';
  const secondary = document.createElement('span');
  secondary.className = 'cpt-secondary';
  status.append(primary, secondary);
  control.append(icon, status, createBrandLockup('compact'));
  container.append(style, control);
  let destroyed = false;
  let locked = false;
  let currentState = options.initialState;
  let successFeedback: SuccessFeedback | undefined;

  const update = (state: WidgetState): void => {
    if (destroyed) return;
    currentState = state;
    const presentation = presentationFor(state);
    primary.textContent = presentation.primary;
    secondary.textContent = state.name === 'success' && successFeedback
      ? [successFeedback.elapsedLabel, successFeedback.percentileLabel].filter(Boolean).join(' · ') || presentation.secondary
      : presentation.secondary;
    control.disabled = presentation.disabled || locked;
    control.setAttribute('aria-label', presentation.actionLabel);
    icon.classList.toggle('cpt-status-icon--checkbox', presentation.icon === 'empty' || presentation.icon === 'progress' || presentation.icon === 'success');
    icon.dataset.tone = presentation.icon === 'success' ? 'success' : presentation.icon === 'error' || presentation.icon === 'expired' ? 'danger' : 'accent';
    icon.replaceChildren();
    if (presentation.icon === 'progress') {
      const spinner = document.createElement('span');
      spinner.className = 'cpt-spinner';
      spinner.setAttribute('aria-hidden', 'true');
      icon.append(spinner);
    } else if (presentation.icon !== 'empty') {
      icon.append(createIcon(presentation.icon));
    }
  };

  const onClick = (event: MouseEvent): void => options.onAction(event);
  control.addEventListener('click', onClick);
  update(options.initialState);

  return {
    update,
    showSuccessFeedback: (feedback) => {
      successFeedback = feedback;
      control.dataset.successPulse = 'true';
      if (currentState.name === 'success') update(currentState);
    },
    setLocked: (next) => { locked = next; update(currentState); },
    focus: () => { if (!destroyed) control.focus(); },
    destroy: () => {
      if (destroyed) return;
      destroyed = true;
      control.removeEventListener('click', onClick);
      style.remove();
      control.remove();
    },
  };
}
