import { normalizeOrder, solvePow, type PowParameters } from './pow.js';

export interface PowRevealResult {
  /** 解出的 PoW nonce（十进制串即服务端私有 order） */
  nonce: number;
  /** 从组件创建到解出的实测耗时（ms），随提交作为 powActualMs 上报 */
  actualMs: number;
}

export interface PowOverlayOptions {
  /** 服务端下发的乱序图 dataURL：每个 div 切片都以它为背景，仅显示其中一块 */
  imageUrl: string;
  pow: PowParameters;
  onRevealed(result: PowRevealResult): void;
  onError?(error: Error): void;
  /** 每次内容变换的间隔（ms），默认 120 */
  tickMs?: number;
  /** 每运算多少次哈希向 UI 回报一次当前 nonce，默认 8 */
  stepEvery?: number;
}

export interface PowOverlayHandle {
  /** 乱序图加载完成即可开始复原变换 */
  readonly ready: Promise<void>;
  /** 网格容器（铺满原图区域，renderer 可将其作为交互目标） */
  readonly element: HTMLElement;
  destroy(): void;
}

/** 复原阶段每个 tick 交换的切片对数（10 片约 5 个 tick 完成复原）。 */
const CONVERGE_PER_TICK = 2;
/** reveal 前至少展示的内容变换时长（ms）。 */
const MIN_SHUFFLE_MS = 600;
/** 求解中两次「同步尝试排列」展示的最小间隔（ms）。 */
const RENDER_STEP_MS = 40;

const POW_OVERLAY_STYLES = '.cpt-pow-grid{position:absolute;inset:0;z-index:0;display:grid;overflow:hidden}.cpt-pow-tile{background-repeat:no-repeat;box-shadow:inset 0 0 0 1px rgba(15,23,42,.06);transition:background-position .09s linear;will-change:background-position}@media (prefers-reduced-motion:reduce){.cpt-pow-tile{transition:none}}';

/**
 * FNV-1a 32 位哈希：由 nonce 派生确定性种子。相邻 nonce 仅末位数字递增，
 * 但种子与排列会显著不同，保证每个展示间隔的尝试位置肉眼可见地变化。
 */
function seedFromNonce(nonce: number): number {
  let hash = 0x811c9dc5;
  for (const char of String(nonce)) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

/**
 * 由任意 nonce 派生一个确定性乱序排列（Fisher-Yates，种子来自 nonce 的 FNV 哈希）。
 * 求解过程中每个展示间隔直接把切片同步到该排列：它是当前正在尝试的 nonce 对应的
 * 块位置，哪怕不是正确解，也能让用户直观看到这些块在尝试求解。
 */
function arrangementFor(nonce: number, cellCount: number): number[] {
  const arrangement = Array.from({ length: cellCount }, (_, index) => index);
  let seed = seedFromNonce(nonce);
  for (let index = arrangement.length - 1; index > 0; index -= 1) {
    seed = Math.imul(seed ^ (seed >>> 15), 0x2c1b3c6d) >>> 0;
    const swap = seed % (index + 1);
    [arrangement[index], arrangement[swap]] = [arrangement[swap]!, arrangement[index]!];
  }
  return arrangement;
}

/** CSS sprite 定位：把整图作为背景，块 cell 的 background-position 百分比。 */
function spritePosition(cell: number, cols: number, rows: number): string {
  const col = cell % cols;
  const row = Math.floor(cell / cols);
  const x = (col / Math.max(cols - 1, 1)) * 100;
  const y = (row / Math.max(rows - 1, 1)) * 100;
  return `${x}% ${y}%`;
}

export function renderPowOverlay(container: HTMLElement | ShadowRoot, options: PowOverlayOptions): PowOverlayHandle {
  const { imageUrl, pow } = options;
  const tickMs = options.tickMs ?? 120;
  const stepEvery = options.stepEvery ?? 8;
  const cols = pow.gridCols;
  const rows = pow.gridRows;
  const cellCount = cols * rows;
  const minShuffleMs = pow.minShuffleMs ?? MIN_SHUFFLE_MS;
  const style = document.createElement('style');
  style.textContent = POW_OVERLAY_STYLES;
  const grid = document.createElement('div');
  grid.className = 'cpt-pow-grid';
  grid.style.gridTemplateColumns = `repeat(${cols}, 1fr)`;
  grid.style.gridTemplateRows = `repeat(${rows}, 1fr)`;
  grid.tabIndex = 0;
  grid.setAttribute('role', 'img');
  const source = document.createElement('img');
  source.className = 'cpt-pow-source';
  source.alt = '';
  source.hidden = true;
  container.append(style, grid, source);

  const tiles: HTMLDivElement[] = [];
  for (let index = 0; index < cellCount; index += 1) {
    const tile = document.createElement('div');
    tile.className = 'cpt-pow-tile';
    tile.style.backgroundImage = `url("${imageUrl}")`;
    tile.style.backgroundSize = `${cols * 100}% ${rows * 100}%`;
    grid.append(tile);
    tiles.push(tile);
  }

  const startedAt = Date.now();
  /** cur[i] = 网格第 i 个切片当前显示的乱序图块（初始 i，即整个网格拼出乱序图本身） */
  let cur = Array.from({ length: cellCount }, (_, index) => index);
  /** 上一次把切片同步到尝试排列的时刻，用于节流展示频率。 */
  let lastAttemptRenderAt = -Infinity;
  let solvedNonce: number | undefined;
  let solvedInverse: number[] | undefined;
  let destroyed = false;
  let revealed = false;
  let timer: ReturnType<typeof setInterval> | undefined;
  let revealTimer: ReturnType<typeof setTimeout> | undefined;
  let readyResolve = (): void => {};
  let readyReject: (error: Error) => void = () => {};
  const ready = new Promise<void>((resolve, reject) => {
    readyResolve = resolve;
    readyReject = reject;
  });

  /** 把 cur 反映到切片 background-position：切片 i 显示乱序图第 cur[i] 块。 */
  const updateTiles = (): void => {
    for (let index = 0; index < tiles.length; index += 1) {
      tiles[index]!.style.backgroundPosition = spritePosition(cur[index]!, cols, rows);
    }
  };
  /** 把当前显示排列朝目标 target 收敛一步：每 tick 交换 CONVERGE_PER_TICK 对切片的显示内容。 */
  const converge = (target: number[]): void => {
    let fixed = 0;
    for (let index = 0; index < cur.length && fixed < CONVERGE_PER_TICK; index += 1) {
      if (cur[index] === target[index]) continue;
      const holder = cur.indexOf(target[index]!);
      if (holder < 0) break;
      [cur[index], cur[holder]] = [cur[holder]!, cur[index]!];
      fixed += 1;
    }
  };
  const tryReveal = (): void => {
    if (destroyed || revealed || solvedNonce === undefined || solvedInverse === undefined) return;
    if (cur.every((value, index) => value === solvedInverse![index]) && Date.now() - startedAt >= minShuffleMs) {
      reveal(solvedNonce);
    }
  };
  const tick = (): void => {
    if (destroyed || revealed || !solvedInverse) return;
    // 复原阶段：把当前显示排列朝复原排列渐进收敛
    converge(solvedInverse);
    updateTiles();
    tryReveal();
    if (Date.now() - startedAt < 2000) console.log(`[pow] tick converge cur=${cur.join('')} solved=${solvedInverse.join('')}`);
  };
  const startTicker = (): void => {
    if (destroyed) return;
    updateTiles();
    timer = setInterval(tick, tickMs);
  };
  const stopTicker = (): void => {
    if (timer !== undefined) clearInterval(timer);
    timer = undefined;
  };
  const reveal = (nonce: number): void => {
    if (destroyed || revealed) return;
    revealed = true;
    console.log(`[pow] reveal nonce=${nonce} elapsed=${Date.now() - startedAt}ms`);
    stopTicker();
    if (revealTimer !== undefined) clearTimeout(revealTimer);
    options.onRevealed({ nonce, actualMs: Date.now() - startedAt });
  };
  const finish = (nonce: number): void => {
    if (destroyed || revealed) return;
    solvedNonce = nonce;
    const order = normalizeOrder(nonce, cellCount);
    solvedInverse = order.map((_, index) => order.indexOf(index));
    const remaining = Math.max(0, minShuffleMs - (Date.now() - startedAt));
    if (remaining <= 0) {
      cur = [...solvedInverse];
      updateTiles();
      reveal(nonce);
      return;
    }
    // 兜底：若复原变换在剩余时长内未完成，到点直接摆正并 reveal
    revealTimer = setTimeout(() => {
      if (solvedInverse) {
        cur = [...solvedInverse];
        updateTiles();
      }
      reveal(nonce);
    }, remaining);
  };
  const fail = (error: Error): void => {
    if (destroyed || revealed) return;
    stopTicker();
    options.onError?.(error);
  };

  function onLoad(): void {
    if (destroyed) return;
    startTicker();
    readyResolve();
    console.log(`[pow] solve start powStart=${pow.powStart} stepEvery=${stepEvery} tickMs=${tickMs}`);
    void solvePow(pow, {
      stepEvery,
      onStep: (nonce) => {
        // 求解中：跟随哈希进度（节流）把切片同步到当前尝试 nonce 的排列，
        // 让用户直观看到这些块在尝试求解（哪怕展示的位置是错误的）
        const now = Date.now();
        if (now - lastAttemptRenderAt >= RENDER_STEP_MS) {
          lastAttemptRenderAt = now;
          cur = arrangementFor(nonce, cellCount);
          updateTiles();
          console.log(`[pow] render nonce=${nonce} elapsed=${(now - startedAt).toFixed(0)}ms perm=${cur.join('')}`);
        }
      },
    }).then((nonce) => {
      console.log(`[pow] solved nonce=${nonce} elapsed=${Date.now() - startedAt}ms`);
      finish(nonce);
    }, (error: unknown) => {
      console.log('[pow] failed', error);
      fail(error instanceof Error ? error : new Error('POW_UNSOLVED'));
    });
  }
  function onImageError(): void {
    if (!destroyed) {
      fail(new Error('POW_MEDIA_ERROR'));
      readyReject(new Error('POW_MEDIA_ERROR'));
    }
  }
  // 挂载即按初始块位置铺好背景（网格拼出乱序图本身），避免乱序图就绪前全部显示同一块
  updateTiles();
  source.addEventListener('load', onLoad);
  source.addEventListener('error', onImageError);
  source.src = imageUrl;

  return {
    ready,
    element: grid,
    destroy() {
      if (destroyed) return;
      destroyed = true;
      stopTicker();
      if (revealTimer !== undefined) clearTimeout(revealTimer);
      source.removeEventListener('load', onLoad);
      source.removeEventListener('error', onImageError);
      grid.remove();
      source.remove();
      style.remove();
    },
  };
}
