import { PointerTelemetryCollector, type PointerDrag } from '../pointer-telemetry.js';
import { COMPONENT_STYLES, HOST_RESET } from '../styles.js';

export interface DragConfirmResponse {
  schemaVersion: 1;
  interactionNonce: string;
  finalPosition: 1;
}

export type DragConfirmTelemetry = { schemaVersion: 1; mode: 'pointer'; drag: PointerDrag };

export interface DragConfirmRendererOptions {
  interactionNonce: string;
  onSubmit(response: DragConfirmResponse, telemetry: DragConfirmTelemetry): void;
}

export interface DragConfirmRendererHandle {
  setBusy(busy: boolean): void;
  focus(): void;
  destroy(): void;
}

const STYLES = '.cpt-drag-confirm{position:relative;width:100%;height:48px;overflow:hidden;border:1px solid var(--cpt-border);border-radius:var(--cpt-radius,8px);background:var(--cpt-surface);touch-action:none}.cpt-drag-confirm-track{position:absolute;inset:0;display:grid;place-items:center;padding-left:48px;color:var(--cpt-muted);font-size:13px}.cpt-drag-confirm-fill{position:absolute;inset:0 auto 0 0;width:0;background:color-mix(in srgb,var(--cpt-accent) 16%,transparent)}.cpt-drag-confirm-handle{position:absolute;inset:4px auto 4px 4px;display:grid;width:40px;border:0;border-radius:6px;place-items:center;background:var(--cpt-accent);color:var(--cpt-button-text);cursor:grab;touch-action:none;transition:box-shadow .12s ease,scale .12s ease}.cpt-drag-confirm[data-dragging="true"] .cpt-drag-confirm-handle{cursor:grabbing;scale:1.03;box-shadow:0 5px 12px color-mix(in srgb,var(--cpt-accent) 28%,transparent)}.cpt-drag-confirm[data-magnetic="true"] .cpt-drag-confirm-handle{box-shadow:0 0 0 3px color-mix(in srgb,var(--cpt-success) 18%,transparent)}.cpt-drag-confirm[data-returning="true"] .cpt-drag-confirm-handle,.cpt-drag-confirm[data-returning="true"] .cpt-drag-confirm-fill{transition:transform .22s ease,width .22s ease}@media (prefers-reduced-motion:reduce){.cpt-drag-confirm-handle,.cpt-drag-confirm[data-returning="true"] .cpt-drag-confirm-handle,.cpt-drag-confirm[data-returning="true"] .cpt-drag-confirm-fill{transition:none}.cpt-drag-confirm[data-dragging="true"] .cpt-drag-confirm-handle{scale:none}}';

export function renderDragConfirm(container: HTMLElement | ShadowRoot, options: DragConfirmRendererOptions): DragConfirmRendererHandle {
  const style = document.createElement('style');
  style.textContent = `${HOST_RESET}${COMPONENT_STYLES}${STYLES}`;
  const track = document.createElement('div');
  track.className = 'cpt-drag-confirm';
  const fill = document.createElement('span');
  fill.className = 'cpt-drag-confirm-fill';
  const label = document.createElement('span');
  label.className = 'cpt-drag-confirm-track';
  label.textContent = '按住滑块拖到最右侧';
  const handle = document.createElement('button');
  handle.type = 'button';
  handle.className = 'cpt-drag-confirm-handle';
  handle.setAttribute('aria-label', '按住并拖到最右侧完成验证');
  handle.textContent = '→';
  track.append(fill, label, handle);
  container.append(style, track);
  let destroyed = false;
  let busy = false;
  let collector: PointerTelemetryCollector | undefined;
  let offset = 0;
  const range = (): number => Math.max(1, track.getBoundingClientRect().width - 48);
  const position = (event: PointerEvent): number => Math.max(0, Math.min(1, (event.clientX - track.getBoundingClientRect().left - offset) / range()));
  const renderPosition = (value: number): void => {
    track.dataset.magnetic = String(value >= 0.96);
    handle.style.transform = `translateX(${Math.round(value * range())}px)`;
    fill.style.width = `${Math.round(value * 100)}%`;
  };
  const reset = (): void => {
    track.dataset.returning = 'true';
    track.dataset.dragging = 'false';
    handle.style.cursor = 'grab';
    renderPosition(0);
  };
  const abort = (): void => {
    collector?.abort();
    collector = undefined;
    reset();
  };
  const onPointerDown = (event: PointerEvent): void => {
    if (busy || destroyed) return;
    track.dataset.returning = 'false';
    track.dataset.dragging = 'true';
    handle.style.cursor = 'grabbing';
    offset = event.clientX - track.getBoundingClientRect().left;
    const next = new PointerTelemetryCollector({ target: handle, rect: () => ({ left: track.getBoundingClientRect().left + offset, top: track.getBoundingClientRect().top, width: range(), height: track.getBoundingClientRect().height }) });
    if (next.start(event)) collector = next;
    else handle.style.cursor = 'grab';
  };
  const onPointerMove = (event: PointerEvent): void => {
    if (!collector?.move(event)) return;
    renderPosition(position(event));
  };
  const onPointerUp = (event: PointerEvent): void => {
    const active = collector;
    if (!active) return;
    const finalPosition = position(event);
    renderPosition(finalPosition);
    const drag = active.finish(event, 'drag-confirm');
    collector = undefined;
    track.dataset.dragging = 'false';
    handle.style.cursor = 'grab';
    if (drag && finalPosition >= 0.985) options.onSubmit({ schemaVersion: 1, interactionNonce: options.interactionNonce, finalPosition: 1 }, { schemaVersion: 1, mode: 'pointer', drag });
    else reset();
  };
  const onVisibilityChange = (): void => {
    if (document.visibilityState === 'hidden') abort();
  };
  const onPointerCancel = (event: PointerEvent): void => {
    collector?.cancel(event);
    collector = undefined;
    track.dataset.dragging = 'false';
    reset();
  };
  handle.addEventListener('pointerdown', onPointerDown);
  handle.addEventListener('pointermove', onPointerMove);
  handle.addEventListener('pointerup', onPointerUp);
  handle.addEventListener('pointercancel', onPointerCancel);
  window.addEventListener('blur', abort);
  document.addEventListener('visibilitychange', onVisibilityChange);
  return {
    setBusy: (next) => { busy = next; if (next) abort(); handle.disabled = next; track.setAttribute('aria-busy', String(next)); },
    focus: () => handle.focus(),
    destroy: () => {
      if (destroyed) return;
      destroyed = true;
      abort();
      handle.removeEventListener('pointerdown', onPointerDown);
      handle.removeEventListener('pointermove', onPointerMove);
      handle.removeEventListener('pointerup', onPointerUp);
      handle.removeEventListener('pointercancel', onPointerCancel);
      window.removeEventListener('blur', abort);
      document.removeEventListener('visibilitychange', onVisibilityChange);
      track.remove();
      style.remove();
    },
  };
}
