import type { PowParameters } from './pow.js';

export type WidgetStateName =
  | 'idle'
  | 'analyzing'
  | 'ready'
  | 'submitting'
  | 'success'
  | 'error'
  | 'expired'
  | 'destroyed';

export type WidgetState =
  | Readonly<{ name: 'idle' }>
  | Readonly<{ name: 'analyzing' }>
  | Readonly<{ name: 'ready' }>
  | Readonly<{ name: 'submitting' }>
  | Readonly<{ name: 'success'; token: string }>
  | Readonly<{ name: 'error'; error: WidgetError }>
  | Readonly<{ name: 'expired' }>
  | Readonly<{ name: 'destroyed' }>;

export interface WidgetErrorOptions {
  errorCode: string;
  status?: number | undefined;
  requestId?: string | undefined;
  cause?: unknown;
}

export class WidgetError extends Error {
  readonly errorCode: string;
  readonly status: number | undefined;
  readonly requestId: string | undefined;

  constructor(message: string, options: WidgetErrorOptions) {
    super(message, { cause: options.cause });
    this.name = 'WidgetError';
    this.errorCode = options.errorCode;
    this.status = options.status;
    this.requestId = options.requestId;
  }
}

export interface PassedIssueResult {
  outcome: 'passed';
  verificationToken: string;
  expiresAt: string;
}

export interface SpatialChallengeData {
  interactionNonce: string;
  image: string;
  width: 600;
  height: 375;
  pow: PowParameters;
}

export interface SliderChallengeData {
  schemaVersion: 1;
  interactionNonce: string;
  backgroundImage: string;
  pieceImage: string;
  imageWidth: number;
  imageHeight: number;
  pieceWidth: number;
  pieceHeight: number;
  pieceY: number;
  trackStartX: number;
  pow: PowParameters;
}

export interface PuzzlePieceData {
  id: string;
  image: string;
  width: number;
  height: number;
}

export interface PuzzleChallengeData {
  schemaVersion: 1;
  interactionNonce: string;
  backgroundImage: string;
  imageWidth: number;
  imageHeight: number;
  pieces: readonly [PuzzlePieceData, PuzzlePieceData, PuzzlePieceData];
  pow: PowParameters;
}

export interface RotatePuzzleChallengeData {
  schemaVersion: 1;
  interactionNonce: string;
  fixedImage: string;
  rotatingImage: string;
  imageSize: number;
  rotatingPart: 'ring' | 'inner';
  maxRotationDegrees: number;
  direction: -1 | 1;
  pow: PowParameters;
}

export interface StandardChallengeIssueResult {
  outcome: 'challenge';
  challengeId: string;
  kind: 'click' | 'drag_confirm' | 'decoy' | 'ghost';
  expiresAt: string;
  data: Record<string, unknown>;
}

export interface SliderChallengeIssueResult {
  outcome: 'challenge';
  challengeId: string;
  kind: 'slider';
  expiresAt: string;
  data: SliderChallengeData;
}

export interface PuzzleChallengeIssueResult {
  outcome: 'challenge';
  challengeId: string;
  kind: 'puzzle';
  expiresAt: string;
  data: PuzzleChallengeData;
}

export interface RotatePuzzleChallengeIssueResult {
  outcome: 'challenge';
  challengeId: string;
  kind: 'rotate_puzzle';
  expiresAt: string;
  data: RotatePuzzleChallengeData;
}

export interface SpatialChallengeIssueResult {
  outcome: 'challenge';
  challengeId: string;
  kind: 'spatial';
  expiresAt: string;
  data: SpatialChallengeData;
}

export type ChallengeIssueResult = StandardChallengeIssueResult | SliderChallengeIssueResult | PuzzleChallengeIssueResult | RotatePuzzleChallengeIssueResult | SpatialChallengeIssueResult;

export type IssueResult = PassedIssueResult | ChallengeIssueResult;

export interface WidgetTheme {
  mode?: 'light' | 'dark' | 'auto';
  accentColor?: string;
  successColor?: string;
  dangerColor?: string;
  textColor?: string;
  surfaceColor?: string;
  borderColor?: string;
  borderRadius?: number;
  fontFamily?: string;
}

export interface WidgetOptions {
  apiBaseUrl: string;
  siteKey: string;
  purpose: string;
  language?: 'zh-CN' | 'en-US';
  appearance?: 'compact' | 'normal';
  theme?: WidgetTheme;
  autoExecute?: boolean;
  onStateChange?: (state: WidgetState) => void;
  onSuccess(token: string): void;
  onError?: (error: WidgetError) => void;
  onExpired?: () => void;
}

export interface WidgetInstance {
  execute(): Promise<void>;
  reset(): void;
  destroy(): void;
}
