import type { SuccessFeedback } from '../success-feedback.js';

export interface SuccessFeedbackHandle {
  readonly finished: Promise<void>;
  destroy(): void;
}

export function renderSuccessFeedback(container: HTMLElement, feedback: SuccessFeedback, onFinished?: () => void): SuccessFeedbackHandle {
  const root = document.createElement('section');
  root.className = 'cpt-success-feedback';
  root.dataset.tone = feedback.tone;
  root.setAttribute('role', 'status');
  root.setAttribute('aria-live', 'polite');
  root.setAttribute('aria-atomic', 'true');
  const ripple = document.createElement('span');
  ripple.className = 'cpt-success-ripple';
  ripple.setAttribute('aria-hidden', 'true');
  const icon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  icon.classList.add('cpt-success-check');
  icon.dataset.icon = 'success';
  icon.setAttribute('viewBox', '0 0 64 64');
  icon.setAttribute('aria-hidden', 'true');
  const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
  circle.setAttribute('cx', '32');
  circle.setAttribute('cy', '32');
  circle.setAttribute('r', '29');
  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  path.setAttribute('d', 'M19 33l9 9 18-20');
  icon.append(circle, path);
  const copy = document.createElement('span');
  copy.className = 'cpt-success-copy';
  const headline = document.createElement('strong');
  headline.className = 'cpt-success-headline';
  headline.textContent = feedback.headline;
  copy.append(headline);
  if (feedback.elapsedLabel) {
    const elapsed = document.createElement('span');
    elapsed.className = 'cpt-success-elapsed';
    elapsed.textContent = feedback.elapsedLabel;
    copy.append(elapsed);
  }
  if (feedback.percentileLabel) {
    const percentile = document.createElement('span');
    percentile.className = 'cpt-success-percentile';
    percentile.textContent = feedback.percentileLabel;
    copy.append(percentile);
  }
  root.append(ripple, icon, copy);
  container.append(root);
  let settled = false;
  let resolveFinished!: () => void;
  const finished = new Promise<void>((resolve) => { resolveFinished = resolve; });
  const timer = setTimeout(() => finish(true), 720);
  const finish = (notify: boolean): void => {
    if (settled) return;
    settled = true;
    clearTimeout(timer);
    root.removeEventListener('animationend', onAnimationEnd);
    if (notify) onFinished?.();
    resolveFinished();
  };
  function onAnimationEnd(event: AnimationEvent): void {
    if (event.target === root) finish(true);
  }
  root.addEventListener('animationend', onAnimationEnd);
  return {
    finished,
    destroy: () => {
      finish(false);
      root.remove();
    },
  };
}
