export type TimedChallengeKind = 'slider' | 'puzzle' | 'rotate_puzzle' | 'spatial' | 'decoy' | 'ghost';

export interface SuccessFeedback {
  readonly headline: string;
  readonly elapsedLabel?: string;
  readonly percentileLabel?: string;
  readonly tone: 'fast' | 'average' | 'slow' | 'neutral';
}

interface TimingProfile {
  readonly baselineMs: number;
  readonly fastMs: number;
  readonly slowMs: number;
}

const PROFILES: Readonly<Record<TimedChallengeKind, TimingProfile>> = {
  slider: { baselineMs: 7_000, fastMs: 2_500, slowMs: 30_000 },
  puzzle: { baselineMs: 12_000, fastMs: 3_500, slowMs: 40_000 },
  rotate_puzzle: { baselineMs: 9_000, fastMs: 3_000, slowMs: 35_000 },
  spatial: { baselineMs: 9_000, fastMs: 3_000, slowMs: 35_000 },
  decoy: { baselineMs: 10_000, fastMs: 3_000, slowMs: 35_000 },
  ghost: { baselineMs: 12_000, fastMs: 3_500, slowMs: 40_000 },
};

function elapsedLabel(elapsedMs: number): string {
  if (elapsedMs < 60_000) return `用时 ${(elapsedMs / 1_000).toFixed(1)} 秒`;
  const minutes = Math.floor(elapsedMs / 60_000);
  const seconds = Math.floor(elapsedMs % 60_000 / 1_000);
  return `用时 ${minutes} 分 ${String(seconds).padStart(2, '0')} 秒`;
}

function percentile(elapsedMs: number, baselineMs: number): number {
  const estimate = Math.round(100 / (1 + Math.exp((elapsedMs - baselineMs) / (baselineMs * 0.3))));
  return Math.max(18, Math.min(96, estimate));
}

export function createSuccessFeedback(kind: TimedChallengeKind, elapsedMs: number): SuccessFeedback {
  if (!Number.isFinite(elapsedMs) || elapsedMs < 0) return { headline: '验证通过', tone: 'neutral' };
  const profile = PROFILES[kind];
  const elapsed = elapsedLabel(elapsedMs);
  const restored = kind === 'rotate_puzzle';
  if (elapsedMs >= profile.slowMs) return { headline: restored ? '图片已复原' : '验证完成', elapsedLabel: elapsed, tone: 'slow' };
  const rank = `比约 ${percentile(elapsedMs, profile.baselineMs)}% 的用户更快`;
  if (elapsedMs <= profile.fastMs) return { headline: restored ? '很棒，图片已复原' : '很棒，验证完成', elapsedLabel: elapsed, percentileLabel: rank, tone: 'fast' };
  return { headline: restored ? '图片已复原' : '完成得不错', elapsedLabel: elapsed, percentileLabel: rank, tone: 'average' };
}
