export interface PowParameters {
  /** 客户端从该 nonce 起递增暴力搜索 */
  powStart: number;
  /** sha256(order + salt) 的完整 64 位 hex digest */
  powTarget: string;
  powSalt: string;
  gridCols: number;
  gridRows: number;
  /** 客户端渲染调优：reveal 前至少展示的动画时长（ms），缺省 600。服务端不下发，测试可置 0。 */
  minShuffleMs?: number;
}

/** 用 Web Crypto 计算 SHA-256 hex digest。 */
export async function sha256Hex(text: string): Promise<string> {
  const bytes = new TextEncoder().encode(text);
  const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

export interface SolvePowOptions {
  /** 每运算 stepEvery 次哈希回调一次当前尝试的 nonce，供 UI 展示中间排列状态 */
  stepEvery?: number;
  onStep?(nonce: number): void;
  signal?: AbortSignal;
}

/**
 * 从 powStart 递增暴力搜索唯一命中点：sha256(nonce 十进制串 + salt) === powTarget。
 * 命中 nonce 的十进制串就是服务端私有 order（0~9 排列，非 0 开头），
 * 由它还原乱序图块排列。搜索范围受 difficultyDistance 约束，通常 ≤ 65536 次，
 * maxAttempts 作为防御上限，避免异常参数导致客户端无限循环。
 * 传入 stepEvery/onStep 时，每运算 stepEvery 次会回报当前 nonce，供前端分步展示。
 */
export async function solvePow(
  pow: Pick<PowParameters, 'powStart' | 'powTarget' | 'powSalt'>,
  maxAttemptsOrOptions: number | SolvePowOptions = 1_000_000,
): Promise<number> {
  const options: { maxAttempts?: number; stepEvery?: number; onStep?: (nonce: number) => void; signal?: AbortSignal } =
    typeof maxAttemptsOrOptions === 'number' ? { maxAttempts: maxAttemptsOrOptions } : maxAttemptsOrOptions;
  const { maxAttempts = 1_000_000, stepEvery = 0, onStep, signal } = options;
  const { powStart, powTarget, powSalt } = pow;
  const start = Math.max(0, Math.floor(powStart));
  for (let nonce = start; nonce < start + maxAttempts; nonce += 1) {
    if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');
    if (stepEvery > 0 && (nonce - start) % stepEvery === 0) onStep?.(nonce);
    if (await sha256Hex(`${nonce}${powSalt}`) === powTarget) return nonce;
  }
  throw new Error('POW_UNSOLVED');
}

/**
 * 把解出的 nonce 十进制串转成网格块排列 order[j] = 原图第 j 格的目标格。
 * 服务端乱序图位置 j 放的是原图块 order[j]；前端 div 切片「第 j 片」移动到
 * 目标格 order[j] 即可完成重组。
 */
export function normalizeOrder(nonce: number, cellCount = 10): number[] {
  const digits = String(nonce).split('').map(Number);
  if (digits.length !== cellCount) throw new Error('POW_ORDER_LENGTH');
  if (new Set(digits).size !== cellCount) throw new Error('POW_ORDER_DUPLICATE');
  return digits;
}
