export interface ImagePreparationOptions {
  signal?: AbortSignal;
  timeoutMs?: number;
  createImage?: () => HTMLImageElement;
}

export interface ImagePreparation {
  readonly images: readonly HTMLImageElement[];
  readonly ready: Promise<readonly HTMLImageElement[]>;
  destroy(): void;
}

function abortError(): Error {
  const error = new Error('AbortError');
  error.name = 'AbortError';
  return error;
}

export function prepareImages(sources: readonly string[], options: ImagePreparationOptions = {}): ImagePreparation {
  const images = sources.map(() => options.createImage?.() ?? new Image());
  for (const image of images) image.draggable = false;
  let settled = false;
  let rejectReady: (reason: unknown) => void = () => undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const listeners: Array<() => void> = [];

  const clear = (): void => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
    options.signal?.removeEventListener('abort', onAbort);
    for (const remove of listeners.splice(0)) remove();
  };
  const clearSources = (): void => {
    for (const image of images) image.src = '';
  };
  const fail = (error: Error): void => {
    if (settled) return;
    settled = true;
    clear();
    clearSources();
    rejectReady(error);
  };
  const onAbort = (): void => fail(abortError());
  const ready = new Promise<readonly HTMLImageElement[]>((resolve, reject) => {
    rejectReady = reject;
    if (options.signal?.aborted) {
      fail(abortError());
      return;
    }
    if (images.length === 0) {
      settled = true;
      resolve(images);
      return;
    }
    let loaded = 0;
    images.forEach((image, index) => {
      const onLoad = (): void => {
        loaded += 1;
        if (loaded !== images.length || settled) return;
        settled = true;
        clear();
        resolve(images);
      };
      const onError = (): void => fail(new Error('CORPTCHA_MEDIA_ERROR'));
      image.addEventListener('load', onLoad, { once: true });
      image.addEventListener('error', onError, { once: true });
      listeners.push(() => {
        image.removeEventListener('load', onLoad);
        image.removeEventListener('error', onError);
      });
      image.src = sources[index]!;
    });
    options.signal?.addEventListener('abort', onAbort, { once: true });
    timer = setTimeout(() => fail(new Error('CORPTCHA_MEDIA_TIMEOUT')), options.timeoutMs ?? 10_000);
  });
  void ready.catch(() => undefined);

  return {
    images,
    ready,
    destroy: () => {
      if (!settled) fail(abortError());
      else {
        clear();
        clearSources();
      }
    },
  };
}
