import { CorptchaClient } from './client.js';
import { BUILD_INFO } from './build-info.js';
import { renderCharacter, type CharacterChallenge, type CharacterRendererHandle } from './renderers/character.js';
import { renderCompact, type CompactRendererHandle } from './renderers/compact.js';
import { renderDragConfirm, type DragConfirmRendererHandle, type DragConfirmResponse, type DragConfirmTelemetry } from './renderers/drag-confirm.js';
import { renderPuzzle, type PuzzleRendererHandle, type PuzzleResponse, type PuzzleTelemetry } from './renderers/puzzle.js';
import { renderRotatePuzzle, type RotatePuzzleRendererHandle, type RotatePuzzleResponse, type RotatePuzzleTelemetry } from './renderers/rotate-puzzle.js';
import { renderSlider, type SliderRendererHandle, type SliderResponse, type SliderTelemetry } from './renderers/slider.js';
import { renderSpatial, type SpatialChallengeView, type SpatialPoint } from './renderers/spatial.js';
import { renderSuccessFeedback, type SuccessFeedbackHandle } from './renderers/success-feedback.js';
import { collectSignals, createBehaviorTracker } from './signals.js';
import { createStateController } from './state.js';
import { parseTheme } from './styles.js';
import { createSuccessFeedback, type SuccessFeedback, type TimedChallengeKind } from './success-feedback.js';
import { createThemeController, type EffectiveTheme, type ThemeController } from './theme-controller.js';
import { WidgetError, type ChallengeIssueResult, type WidgetInstance, type WidgetOptions, type WidgetState } from './types.js';
import type { PowRevealResult } from './pow-overlay.js';
import type { PowParameters } from './pow.js';

interface InternalWidgetOptions extends WidgetOptions {
  fetcher?: typeof fetch;
}

interface ChallengeCandidate {
  layer: HTMLDivElement;
  character?: CharacterRendererHandle;
  spatial?: SpatialChallengeView;
  slider?: SliderRendererHandle;
  puzzle?: PuzzleRendererHandle;
  rotatePuzzle?: RotatePuzzleRendererHandle;
  dragConfirm?: DragConfirmRendererHandle;
  ready: Promise<void>;
}

function waitFor(milliseconds: number, signal: AbortSignal): Promise<boolean> {
  if (signal.aborted) return Promise.resolve(false);
  return new Promise((resolve) => {
    const finish = (completed: boolean): void => {
      clearTimeout(timer);
      signal.removeEventListener('abort', onAbort);
      resolve(completed);
    };
    const onAbort = (): void => finish(false);
    const timer = setTimeout(() => finish(true), Math.max(0, milliseconds));
    signal.addEventListener('abort', onAbort, { once: true });
  });
}

export class CorptchaWidget implements WidgetInstance {
  private readonly host = document.createElement('div');
  private readonly root = this.host.attachShadow({ mode: 'closed' });
  private readonly compactLayer = document.createElement('div');
  private readonly challengeLayer = document.createElement('div');
  private readonly client: CorptchaClient;
  private readonly behavior = createBehaviorTracker(window);
  private readonly state = createStateController((next) => this.invokeCallback(this.options.onStateChange, next));
  private readonly compact: CompactRendererHandle;
  private readonly themeController: ThemeController;
  private challenge: ChallengeIssueResult | undefined;
  private refreshOnlyChallengeId: string | undefined;
  private character: CharacterRendererHandle | undefined;
  private spatial: SpatialChallengeView | undefined;
  private slider: SliderRendererHandle | undefined;
  private puzzle: PuzzleRendererHandle | undefined;
  private rotatePuzzle: RotatePuzzleRendererHandle | undefined;
  private dragConfirm: DragConfirmRendererHandle | undefined;
  private successFeedback: SuccessFeedbackHandle | undefined;
  private operation: AbortController | undefined;
  private refreshGeneration: number | undefined;
  private generation = 0;
  private expirationTimer: ReturnType<typeof setTimeout> | undefined;
  private destroyed = false;
  private startedAt = 0;
  private challengeStartedAt = 0;

  constructor(private readonly container: HTMLElement, private readonly options: InternalWidgetOptions) {
    this.client = new CorptchaClient(options, options.fetcher);
    const theme = parseTheme(options.theme);
    this.host.dataset.corptchaHost = '';
    this.host.dataset.appearance = options.appearance ?? 'compact';
    this.themeController = createThemeController(theme.mode, document.documentElement, (next) => this.applyTheme(next));
    this.applyTheme(this.themeController.theme);
    this.host.lang = options.language ?? 'zh-CN';
    for (const [name, value] of Object.entries({
      all: 'initial',
      display: 'block',
      width: '100%',
      minWidth: '0',
      height: 'auto',
      transform: 'none',
      position: 'static',
      boxSizing: 'border-box',
    })) this.host.style.setProperty(name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`), value, 'important');
    for (const [name, value] of Object.entries(theme.variables)) this.host.style.setProperty(name, value);
    this.root.append(this.compactLayer, this.challengeLayer);
    this.compact = renderCompact(this.compactLayer, {
      initialState: this.state.getSnapshot(),
      onAction: (event) => this.handleCompactAction(event),
    });
    this.container.append(this.host);
    if (options.autoExecute) queueMicrotask(() => { if (!this.destroyed) void this.execute(); });
  }

  async execute(): Promise<void> {
    if (this.destroyed) return;
    const { controller, generation } = this.beginOperation();
    this.returnToIdle();
    this.clearView();
    this.transition({ name: 'analyzing' });
    try {
      this.startedAt = performance.now();
      const signals = collectSignals({ buildInfo: BUILD_INFO, window, navigator, screen, behavior: this.behavior.snapshot(), theme: this.themeController.theme });
      const result = await this.client.issue(signals, controller.signal);
      if (!this.isCurrent(generation)) return;
      if (result.outcome === 'passed') {
        if (!await waitFor(Math.max(0, 200 - (performance.now() - this.startedAt)), controller.signal) || !this.isCurrent(generation)) return;
        this.transition({ name: 'success', token: result.verificationToken });
        if (!await waitFor(150, controller.signal) || !this.isCurrent(generation)) return;
        this.invokeCallback(this.options.onSuccess, result.verificationToken);
        this.scheduleExpiration(result.expiresAt, generation);
        return;
      }
      const challenge = result;
      this.challenge = challenge;
      this.refreshOnlyChallengeId = undefined;
      switch (challenge.kind) {
        case 'click':
          break;
        case 'drag_confirm':
          this.dragConfirm = this.createDragConfirmRenderer(this.challengeLayer, challenge);
          break;
        case 'slider':
          this.slider = this.createSliderRenderer(this.challengeLayer, challenge);
          await this.slider.ready;
          break;
        case 'puzzle':
          this.puzzle = this.createPuzzleRenderer(this.challengeLayer, challenge);
          await this.puzzle.ready;
          break;
        case 'rotate_puzzle':
          this.rotatePuzzle = this.createRotatePuzzleRenderer(this.challengeLayer, challenge);
          await this.rotatePuzzle.ready;
          break;
        case 'decoy':
          this.renderCharacterChallenge('decoy');
          break;
        case 'ghost':
          this.renderCharacterChallenge('ghost');
          break;
        case 'spatial':
          this.renderSpatialChallenge();
          break;
        default:
          throw new Error('CORPTCHA_UNSUPPORTED_CHALLENGE_KIND');
      }
      if (this.isCurrent(generation)) {
        this.challengeStartedAt = performance.now();
        this.transition({ name: 'ready' });
      }
    } catch (error) {
      if (this.isCurrent(generation) && !controller.signal.aborted) this.fail(error);
    }
  }

  reset(): void {
    if (this.destroyed) return;
    this.cancelOperation();
    this.returnToIdle();
    this.clearView();
  }

  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.cancelOperation();
    this.clearView();
    this.transition({ name: 'destroyed' });
    this.compact.destroy();
    this.behavior.destroy();
    this.themeController.destroy();
    this.host.remove();
  }

  private applyTheme(theme: EffectiveTheme): void {
    this.host.dataset.theme = theme;
    this.host.style.colorScheme = theme;
  }

  private clearView(): void {
    this.compact.setLocked(false);
    this.character?.destroy();
    this.character = undefined;
    this.spatial?.destroy();
    this.spatial = undefined;
    this.slider?.destroy();
    this.slider = undefined;
    this.puzzle?.destroy();
    this.puzzle = undefined;
    this.rotatePuzzle?.destroy();
    this.rotatePuzzle = undefined;
    this.dragConfirm?.destroy();
    this.dragConfirm = undefined;
    this.successFeedback?.destroy();
    this.successFeedback = undefined;
    this.challenge = undefined;
    this.refreshOnlyChallengeId = undefined;
    this.clearExpirationTimer();
    this.challengeLayer.replaceChildren();
  }

  private renderCharacterChallenge(kind: 'decoy' | 'ghost'): void {
    if (!this.challenge || this.challenge.kind !== kind) throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    this.character = this.createCharacterRenderer(this.challengeLayer, this.challenge);
  }

  private createCharacterRenderer(container: HTMLElement | ShadowRoot, challenge: ChallengeIssueResult): CharacterRendererHandle {
    const characterChallenge = this.toCharacterChallenge(challenge);
    const restoreFocus = this.compactLayer.querySelector('button');
    if (!restoreFocus) throw new Error('CORPTCHA_COMPACT_UNAVAILABLE');
    const character = renderCharacter(container, {
      challenge: characterChallenge,
      restoreFocus,
      onSubmit: (answer, pow) => void this.submitCharacter(answer, pow),
      onRefresh: () => void this.refresh(),
      onClose: () => {
        if (this.character !== character) return;
        this.character = undefined;
        this.reset();
      },
      onMediaError: (error) => {
        if (!this.destroyed && this.character === character) this.fail(error);
      },
    });
    return character;
  }

  private async submitCharacter(answer: string, pow: PowRevealResult | undefined): Promise<void> {
    if (!this.challenge) return;
    if (!/^[A-Z0-9]{5}$/.test(answer) || !this.startSubmission()) return;
    const challenge = this.challenge;
    const { controller, generation } = this.beginOperation();
    const submissionStartedAt = performance.now();
    this.disableChallengeControls();
    try {
      const elapsedMs = Math.round(performance.now() - this.startedAt);
      const telemetry = { schemaVersion: 1, elapsedMs, eventTrusted: true, pointerType: 'unknown', focusAtAction: document.hasFocus(), visibilityState: document.visibilityState, eventCount: 1, mouseMoves: this.behavior.snapshot().mouseMoves };
      const body = pow
        ? { schemaVersion: 1, interactionNonce: this.requireStringDataFrom(challenge, 'interactionNonce'), answer, powNonce: pow.nonce }
        : { schemaVersion: 1, interactionNonce: this.requireStringDataFrom(challenge, 'interactionNonce'), answer };
      const result = await this.client.submit(challenge.challengeId, body, pow ? { ...telemetry, powActualMs: pow.actualMs } : telemetry, controller.signal);
      const remainingSubmittingMs = Math.max(0, 200 - (performance.now() - submissionStartedAt));
      if (!await waitFor(remainingSubmittingMs, controller.signal) || !this.isCurrent(generation)) return;
      this.character?.showSuccess();
      if (!await waitFor(150, controller.signal) || !this.isCurrent(generation)) return;
      this.character?.startLeaving();
      if (!await waitFor(160, controller.signal) || !this.isCurrent(generation)) return;
      this.character?.destroy();
      this.character = undefined;
      this.completeSubmission(result.verificationToken, challenge, generation);
    } catch (error) {
      if (this.isCurrent(generation) && !controller.signal.aborted) {
        const recovery = this.handleSubmissionFailure(error, challenge, controller, generation);
        const invalid = typeof recovery === 'boolean' ? recovery : await recovery;
        if (!invalid) {
          this.transition({ name: 'ready' });
          this.character?.setSubmitting(false);
          this.character?.focus();
        }
      }
    }
  }

  private renderSpatialChallenge(): void {
    if (!this.challenge || this.challenge.kind !== 'spatial') throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    this.spatial = this.createSpatialRenderer(this.challengeLayer, this.challenge);
  }

  private createSpatialRenderer(container: HTMLElement | ShadowRoot, challenge: ChallengeIssueResult): SpatialChallengeView {
    if (challenge.kind !== 'spatial') throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    const restoreFocus = this.compactLayer.querySelector('button');
    if (!restoreFocus) throw new Error('CORPTCHA_COMPACT_UNAVAILABLE');
    const spatial = renderSpatial(container, {
      data: challenge.data,
      restoreFocus,
      onConfirm: (point, event, pow) => void this.submitSpatial(point, event, pow),
      onRefresh: () => void this.refresh(),
      onClose: () => {
        if (this.spatial !== spatial) return;
        this.spatial = undefined;
        this.reset();
      },
      onMediaError: (error) => {
        if (!this.destroyed && this.spatial === spatial) this.fail(error);
      },
    });
    return spatial;
  }

  private async submitSpatial(point: SpatialPoint, event: Event, pow: PowRevealResult): Promise<void> {
    if (!this.challenge || this.challenge.kind !== 'spatial' || !this.startSubmission()) return;
    const challenge = this.challenge;
    const { controller, generation } = this.beginOperation();
    const submissionStartedAt = performance.now();
    this.disableChallengeControls();
    try {
      const elapsedMs = Math.max(0, Math.round(performance.now() - this.startedAt));
      const pointerType = 'pointerType' in event && typeof event.pointerType === 'string' ? event.pointerType || 'unknown' : 'keyboard';
      const telemetry = { schemaVersion: 1, elapsedMs, eventTrusted: event.isTrusted, pointerType, focusAtAction: document.hasFocus(), visibilityState: document.visibilityState, eventCount: 1, mouseMoves: this.behavior.snapshot().mouseMoves };
      const result = await this.client.submit(challenge.challengeId, { schemaVersion: 1, interactionNonce: challenge.data.interactionNonce, point: { x: point.x, y: point.y }, powNonce: pow.nonce }, { ...telemetry, powActualMs: pow.actualMs }, controller.signal);
      const remainingSubmittingMs = Math.max(0, 200 - (performance.now() - submissionStartedAt));
      if (!await waitFor(remainingSubmittingMs, controller.signal) || !this.isCurrent(generation)) return;
      this.spatial?.showSuccess();
      if (!await waitFor(150, controller.signal) || !this.isCurrent(generation)) return;
      this.spatial?.startLeaving();
      if (!await waitFor(160, controller.signal) || !this.isCurrent(generation)) return;
      this.spatial?.destroy();
      this.spatial = undefined;
      this.completeSubmission(result.verificationToken, challenge, generation);
    } catch (error) {
      if (this.isCurrent(generation) && !controller.signal.aborted) {
        const recovery = this.handleSubmissionFailure(error, challenge, controller, generation);
        const invalid = typeof recovery === 'boolean' ? recovery : await recovery;
        if (!invalid) {
          this.transition({ name: 'ready' });
          this.spatial?.setBusy(false);
          this.spatial?.focus();
        }
      }
    }
  }

  private async refresh(challengeId = this.challenge?.challengeId): Promise<void> {
    if (this.destroyed || this.refreshGeneration !== undefined || !this.challenge || !challengeId || this.challenge.challengeId !== challengeId) return;
    const previous = this.challenge;
    const character = this.character;
    const spatial = this.spatial;
    const slider = this.slider;
    const puzzle = this.puzzle;
    const rotatePuzzle = this.rotatePuzzle;
    const dragConfirm = this.dragConfirm;
    let candidate: ChallengeCandidate | undefined;
    let replacementIssued = false;
    const { controller, generation } = this.beginOperation();
    this.refreshGeneration = generation;
    character?.setRefreshing(true);
    spatial?.setRefreshing(true);
    slider?.setRefreshing(true);
    puzzle?.setRefreshing(true);
    rotatePuzzle?.setRefreshing(true);
    try {
      const signals = collectSignals({ buildInfo: BUILD_INFO, window, navigator, screen, behavior: this.behavior.snapshot(), theme: this.themeController.theme });
      const refreshed = await this.client.refresh(previous.challengeId, signals, controller.signal);
      if (!this.isCurrent(generation) || this.character !== character || this.spatial !== spatial) return;
      this.challenge = refreshed;
      this.refreshOnlyChallengeId = refreshed.challengeId;
      replacementIssued = true;
      if (previous.kind === 'spatial' && refreshed.kind === 'spatial' && spatial) {
        await spatial.replace(refreshed.data, controller.signal);
        if (!this.isCurrent(generation) || this.spatial !== spatial || this.challenge !== refreshed) return;
        this.refreshOnlyChallengeId = undefined;
        spatial.setBusy(false);
        spatial.setRefreshing(false);
        if (this.state.getSnapshot().name === 'error') this.transition({ name: 'ready' });
        spatial.focus();
        return;
      }
      if ((previous.kind === 'decoy' || previous.kind === 'ghost') && (refreshed.kind === 'decoy' || refreshed.kind === 'ghost') && character) {
        await character.replace(this.toCharacterChallenge(refreshed));
        if (!this.isCurrent(generation) || this.character !== character || this.challenge !== refreshed) return;
        this.refreshOnlyChallengeId = undefined;
        character.setSubmitting(false);
        character.setRefreshing(false);
        if (this.state.getSnapshot().name === 'error') this.transition({ name: 'ready' });
        character.focus();
        return;
      }
      candidate = this.createChallengeCandidate(refreshed);
      await candidate.ready;
      if (!this.isCurrent(generation) || this.character !== character || this.spatial !== spatial || this.challenge !== refreshed) {
        candidate.character?.destroy();
        candidate.spatial?.destroy();
        candidate.slider?.destroy();
        candidate.puzzle?.destroy();
        candidate.rotatePuzzle?.destroy();
        candidate.dragConfirm?.destroy();
        return;
      }
      this.character = candidate.character;
      this.spatial = candidate.spatial;
      this.slider = candidate.slider;
      this.puzzle = candidate.puzzle;
      this.rotatePuzzle = candidate.rotatePuzzle;
      this.dragConfirm = candidate.dragConfirm;
      this.challengeLayer.replaceChildren(...candidate.layer.childNodes);
      this.challengeStartedAt = performance.now();
      character?.destroy();
      spatial?.destroy();
      slider?.destroy();
      puzzle?.destroy();
      rotatePuzzle?.destroy();
      dragConfirm?.destroy();
      this.refreshOnlyChallengeId = undefined;
      if (this.state.getSnapshot().name === 'error') this.transition({ name: 'ready' });
      candidate.character?.focus();
      candidate.spatial?.focus();
      candidate.slider?.focus();
      candidate.puzzle?.focus();
      candidate.rotatePuzzle?.focus();
      candidate.dragConfirm?.focus();
    } catch (error) {
      candidate?.character?.destroy();
      candidate?.spatial?.destroy();
      candidate?.slider?.destroy();
      candidate?.puzzle?.destroy();
      candidate?.rotatePuzzle?.destroy();
      candidate?.dragConfirm?.destroy();
      if (this.isCurrent(generation) && !controller.signal.aborted && this.character === character && this.spatial === spatial) {
        if (replacementIssued) {
          character?.setRefreshing(false);
          spatial?.setRefreshing(false);
          this.fail(error);
        }
        else {
          character?.setRefreshing(false);
          spatial?.setRefreshing(false);
          character?.focus();
          spatial?.focus();
          this.invokeCallback(this.options.onError, this.normalizeError(error, 'CORPTCHA_REFRESH_FAILED'));
        }
      }
    }
    finally {
      if (this.refreshGeneration === generation) this.refreshGeneration = undefined;
    }
  }

  private createChallengeCandidate(challenge: ChallengeIssueResult): ChallengeCandidate {
    const layer = document.createElement('div');
    if (challenge.kind === 'click') return { layer, ready: Promise.resolve() };
    if (challenge.kind === 'drag_confirm') {
      const dragConfirm = this.createDragConfirmRenderer(layer, challenge);
      return { layer, dragConfirm, ready: Promise.resolve() };
    }
    if (challenge.kind === 'slider') {
      const slider = this.createSliderRenderer(layer, challenge);
      return { layer, slider, ready: slider.ready };
    }
    if (challenge.kind === 'puzzle') {
      const puzzle = this.createPuzzleRenderer(layer, challenge);
      return { layer, puzzle, ready: puzzle.ready };
    }
    if (challenge.kind === 'rotate_puzzle') {
      const rotatePuzzle = this.createRotatePuzzleRenderer(layer, challenge);
      return { layer, rotatePuzzle, ready: rotatePuzzle.ready };
    }
    if (challenge.kind === 'decoy' || challenge.kind === 'ghost') {
      const character = this.createCharacterRenderer(layer, challenge);
      return { layer, character, ready: character.ready };
    }
    if (challenge.kind === 'spatial') {
      const spatial = this.createSpatialRenderer(layer, challenge);
      return { layer, spatial, ready: spatial.ready };
    }
    throw new Error('CORPTCHA_INVALID_REFRESH_KIND');
  }

  private toCharacterChallenge(challenge: ChallengeIssueResult): CharacterChallenge {
    if (challenge.kind === 'decoy') return { kind: 'decoy', prompt: String(challenge.data.prompt ?? '眯起眼睛，输入图中更实心的 5 位字符'), image: this.requireStringDataFrom(challenge, 'image'), pow: this.requirePowDataFrom(challenge) };
    if (challenge.kind === 'ghost') {
      const mediaUrl = this.requireStringDataFrom(challenge, 'mediaUrl');
      return { kind: 'ghost', prompt: String(challenge.data.prompt ?? '请输入动态媒体中的 5 位字符'), mediaType: this.requireStringDataFrom(challenge, 'mediaType') as 'application/vnd.ghost-font-stream', mediaUrl, loadMedia: (signal) => this.client.media(mediaUrl, signal) };
    }
    throw new Error('CORPTCHA_INVALID_REFRESH_KIND');
  }

  private requirePowDataFrom(challenge: ChallengeIssueResult): PowParameters {
    const pow = challenge.data.pow;
    if (typeof pow !== 'object' || pow === null) throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    return pow as PowParameters;
  }

  private requireStringDataFrom(challenge: ChallengeIssueResult, name: string): string {
    if (challenge.kind === 'spatial' || challenge.kind === 'slider' || challenge.kind === 'puzzle' || challenge.kind === 'rotate_puzzle') throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    const value = challenge.data[name];
    if (typeof value !== 'string' || value.length === 0) throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    return value;
  }

  private createSliderRenderer(container: HTMLElement | ShadowRoot, challenge: ChallengeIssueResult): SliderRendererHandle {
    if (challenge.kind !== 'slider') throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    const restoreFocus = this.compactLayer.querySelector('button');
    if (!restoreFocus) throw new Error('CORPTCHA_COMPACT_UNAVAILABLE');
    return renderSlider(container, {
      data: challenge.data,
      restoreFocus,
      onSubmit: (response, telemetry) => void this.submitInteractive(response, telemetry, 'slider'),
      onRefresh: () => void this.refresh(),
      onClose: () => this.reset(),
      onMediaError: (error) => this.fail(error),
    });
  }

  private createDragConfirmRenderer(container: HTMLElement | ShadowRoot, challenge: ChallengeIssueResult): DragConfirmRendererHandle {
    if (challenge.kind !== 'drag_confirm') throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    return renderDragConfirm(container, {
      interactionNonce: this.requireStringDataFrom(challenge, 'interactionNonce'),
      onSubmit: (response, telemetry) => void this.submitDragConfirm(response, telemetry),
    });
  }

  private async submitDragConfirm(response: DragConfirmResponse, telemetry: DragConfirmTelemetry): Promise<void> {
    if (!this.challenge || this.challenge.kind !== 'drag_confirm' || !this.startSubmission()) return;
    const challenge = this.challenge;
    const { controller, generation } = this.beginOperation();
    this.disableChallengeControls();
    try {
      const result = await this.client.submit(challenge.challengeId, { ...response }, telemetry, controller.signal);
      this.completeSubmission(result.verificationToken, challenge, generation);
    } catch (error) {
      if (this.isCurrent(generation) && !controller.signal.aborted) await this.handleSubmissionFailure(error, challenge, controller, generation);
    }
  }

  private createPuzzleRenderer(container: HTMLElement | ShadowRoot, challenge: ChallengeIssueResult): PuzzleRendererHandle {
    if (challenge.kind !== 'puzzle') throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    const restoreFocus = this.compactLayer.querySelector('button');
    if (!restoreFocus) throw new Error('CORPTCHA_COMPACT_UNAVAILABLE');
    return renderPuzzle(container, {
      data: challenge.data,
      restoreFocus,
      onSubmit: (response, telemetry) => void this.submitInteractive(response, telemetry, 'puzzle'),
      onRefresh: () => void this.refresh(),
      onClose: () => this.reset(),
      onMediaError: (error) => this.fail(error),
    });
  }

  private createRotatePuzzleRenderer(container: HTMLElement | ShadowRoot, challenge: ChallengeIssueResult): RotatePuzzleRendererHandle {
    if (challenge.kind !== 'rotate_puzzle') throw new Error('CORPTCHA_INVALID_CHALLENGE_DATA');
    const restoreFocus = this.compactLayer.querySelector('button');
    if (!restoreFocus) throw new Error('CORPTCHA_COMPACT_UNAVAILABLE');
    return renderRotatePuzzle(container, {
      data: challenge.data,
      restoreFocus,
      onSubmit: (response, telemetry) => void this.submitInteractive(response, telemetry, 'rotate_puzzle'),
      onRefresh: () => void this.refresh(),
      onClose: () => this.reset(),
      onMediaError: (error) => this.fail(error),
    });
  }

  private async submitInteractive(response: SliderResponse | PuzzleResponse | RotatePuzzleResponse, telemetry: SliderTelemetry | PuzzleTelemetry | RotatePuzzleTelemetry, kind: 'slider' | 'puzzle' | 'rotate_puzzle'): Promise<void> {
    if (!this.challenge || this.challenge.kind !== kind || !this.startSubmission()) return;
    const challenge = this.challenge;
    const { controller, generation } = this.beginOperation();
    this.disableChallengeControls();
    try {
      const result = await this.client.submit(challenge.challengeId, { ...response }, telemetry, controller.signal);
      if (kind === 'rotate_puzzle') await this.rotatePuzzle?.showSuccess();
      if (!this.isCurrent(generation)) return;
      this.completeSubmission(result.verificationToken, challenge, generation);
    } catch (error) {
      if (this.isCurrent(generation) && !controller.signal.aborted) await this.handleSubmissionFailure(error, challenge, controller, generation);
    }
  }

  private async confirm(event: Event, elapsedOverride?: number): Promise<void> {
    if (!this.challenge || !this.startSubmission()) return;
    const challenge = this.challenge;
    const { controller, generation } = this.beginOperation();
    this.disableChallengeControls();
    try {
      const elapsedMs = elapsedOverride ?? Math.max(0, Math.round(performance.now() - this.startedAt));
      const telemetry = { schemaVersion: 1, elapsedMs, eventTrusted: event.isTrusted, pointerType: 'mouse', focusAtAction: document.hasFocus(), visibilityState: document.visibilityState, eventCount: 1, mouseMoves: this.behavior.snapshot().mouseMoves };
      const result = await this.client.submit(challenge.challengeId, { confirmed: true, interactionNonce: challenge.data.interactionNonce }, telemetry, controller.signal);
      this.completeSubmission(result.verificationToken, challenge, generation);
    } catch (error) {
      if (this.isCurrent(generation) && !controller.signal.aborted) await this.handleSubmissionFailure(error, challenge, controller, generation);
    }
  }

  private handleSubmissionFailure(error: unknown, challenge: ChallengeIssueResult, controller: AbortController, generation: number): boolean | Promise<boolean> {
    const normalized = this.normalizeError(error);
    if (normalized.errorCode === 'CHALLENGE_INVALID_RESPONSE') {
      if (challenge.kind === 'click') {
        this.compact.setLocked(true);
        this.fail(normalized);
        return true;
      }
      return this.recoverInvalidSubmission(normalized, challenge, controller, generation).then(() => true);
    }
    this.fail(normalized);
    return false;
  }

  private async recoverInvalidSubmission(error: unknown, challenge: ChallengeIssueResult, controller: AbortController, generation: number): Promise<void> {
    const normalized = this.normalizeError(error);
    this.refreshOnlyChallengeId = challenge.challengeId;
    this.fail(normalized);
    if (!await waitFor(350, controller.signal) || !this.isCurrent(generation) || this.challenge?.challengeId !== challenge.challengeId) return;
    await this.refresh(challenge.challengeId);
  }

  private normalizeError(error: unknown, fallback = 'CORPTCHA_FAILED'): WidgetError {
    return error instanceof WidgetError
      ? error
      : new WidgetError(error instanceof Error ? error.message : fallback, {
          errorCode: error instanceof Error ? error.message : fallback,
          cause: error,
        });
  }

  private fail(error: unknown): void {
    const normalized = this.normalizeError(error);
    if (!this.destroyed && this.state.getSnapshot().name !== 'error') this.transition({ name: 'error', error: normalized });
    this.invokeCallback(this.options.onError, normalized);
  }

  private beginOperation(): { controller: AbortController; generation: number } {
    this.operation?.abort();
    const controller = new AbortController();
    this.operation = controller;
    this.generation += 1;
    return { controller, generation: this.generation };
  }

  private cancelOperation(): void {
    this.operation?.abort();
    this.operation = undefined;
    this.generation += 1;
  }

  private isCurrent(generation: number): boolean {
    return !this.destroyed && generation === this.generation;
  }

  private startSubmission(): boolean {
    if (this.destroyed || this.refreshOnlyChallengeId !== undefined || this.state.getSnapshot().name !== 'ready') return false;
    this.transition({ name: 'submitting' });
    return true;
  }

  private completeSubmission(token: string, challenge: ChallengeIssueResult, generation: number): void {
    if (!this.isCurrent(generation)) return;
    const feedback = this.feedbackFor(challenge.kind);
    this.compact.showSuccessFeedback(feedback);
    this.transition({ name: 'success', token });
    this.invokeCallback(this.options.onSuccess, token);
    this.scheduleExpiration(challenge.expiresAt, generation);
    if (challenge.kind === 'click' || challenge.kind === 'drag_confirm') {
      this.clearCompletedChallenge(challenge.kind);
      return;
    }
    const dialog = this.challengeLayer.querySelector<HTMLElement>('.cpt-modal');
    if (!dialog) {
      this.clearCompletedChallenge(challenge.kind);
      return;
    }
    this.successFeedback?.destroy();
    this.successFeedback = renderSuccessFeedback(dialog, feedback, () => {
      if (!this.isCurrent(generation)) return;
      this.successFeedback = undefined;
      this.clearCompletedChallenge(challenge.kind);
    });
  }

  private feedbackFor(kind: ChallengeIssueResult['kind']): SuccessFeedback {
    if (kind === 'slider' || kind === 'puzzle' || kind === 'rotate_puzzle' || kind === 'spatial' || kind === 'decoy' || kind === 'ghost') {
      return createSuccessFeedback(kind as TimedChallengeKind, performance.now() - this.challengeStartedAt);
    }
    return { headline: '验证通过', tone: 'neutral' };
  }

  private clearCompletedChallenge(kind: ChallengeIssueResult['kind']): void {
    if (kind === 'slider') {
      this.slider?.destroy();
      this.slider = undefined;
    }
    if (kind === 'puzzle') {
      this.puzzle?.destroy();
      this.puzzle = undefined;
    }
    if (kind === 'rotate_puzzle') {
      this.rotatePuzzle?.destroy();
      this.rotatePuzzle = undefined;
    }
    if (kind === 'drag_confirm') {
      this.dragConfirm?.destroy();
      this.dragConfirm = undefined;
    }
    if (kind === 'spatial') {
      this.spatial?.destroy();
      this.spatial = undefined;
    }
    if (kind === 'decoy' || kind === 'ghost') {
      this.character?.destroy();
      this.character = undefined;
    }
    this.challengeLayer.replaceChildren();
  }

  private scheduleExpiration(expiresAt: string, generation: number): void {
    this.clearExpirationTimer();
    const deadline = Date.parse(expiresAt);
    if (!Number.isFinite(deadline)) return;
    this.expirationTimer = setTimeout(() => {
      if (!this.isCurrent(generation) || this.state.getSnapshot().name !== 'success') return;
      this.transition({ name: 'expired' });
      this.invokeCallback(this.options.onExpired);
    }, Math.max(0, deadline - Date.now()));
  }

  private clearExpirationTimer(): void {
    if (this.expirationTimer !== undefined) clearTimeout(this.expirationTimer);
    this.expirationTimer = undefined;
  }

  private disableChallengeControls(): void {
    for (const control of this.root.querySelectorAll<HTMLButtonElement | HTMLInputElement>('button,input')) control.disabled = true;
    this.character?.setSubmitting(true);
    this.spatial?.setBusy(true);
    this.slider?.setBusy(true);
    this.puzzle?.setBusy(true);
    this.rotatePuzzle?.setBusy(true);
    this.dragConfirm?.setBusy(true);
  }

  private returnToIdle(): void {
    if (this.state.getSnapshot().name !== 'idle') this.transition({ name: 'idle' });
  }

  private transition(next: WidgetState): void {
    this.state.transition(next);
    this.compact.update(next);
  }

  private handleCompactAction(event: MouseEvent): void {
    const current = this.state.getSnapshot().name;
    if (current === 'ready' && this.challenge?.kind === 'click') {
      void this.confirm(event);
      return;
    }
    if (current === 'error' && this.refreshOnlyChallengeId) {
      void this.refresh(this.refreshOnlyChallengeId);
      return;
    }
    if (current === 'idle' || current === 'error' || current === 'expired') void this.execute();
  }

  private invokeCallback<T>(callback: ((value: T) => void) | undefined, value: T): void;
  private invokeCallback(callback: (() => void) | undefined): void;
  private invokeCallback<T>(callback: ((value?: T) => void) | undefined, value?: T): void {
    try {
      callback?.(value);
    } catch {}
  }
}
