export type BuildFormat = 'esm' | 'iife';

declare const __CORPTCHA_VERSION__: string;
declare const __CORPTCHA_FORMAT__: BuildFormat;

export const BUILD_INFO = Object.freeze({
  version: __CORPTCHA_VERSION__,
  format: __CORPTCHA_FORMAT__,
});

export const BUILD_LABEL = `Corptcha ${BUILD_INFO.version} (${BUILD_INFO.format})`;
