import type { WidgetTheme } from './types.js';

const COLOR_VARIABLES = {
  accentColor: '--cpt-accent',
  successColor: '--cpt-success',
  dangerColor: '--cpt-danger',
  textColor: '--cpt-text',
  surfaceColor: '--cpt-surface',
  borderColor: '--cpt-border',
} as const;

export type ThemeVariableName = (typeof COLOR_VARIABLES)[keyof typeof COLOR_VARIABLES] | '--cpt-radius' | '--cpt-font';

export interface ParsedTheme {
  readonly mode: 'light' | 'dark' | 'auto';
  readonly variables: Readonly<Partial<Record<ThemeVariableName, string>>>;
}

const HEX_COLOR = /^#(?:[\da-f]{3}|[\da-f]{4}|[\da-f]{6}|[\da-f]{8})$/i;
const RGB_COLOR = /^rgba?\(\s*([^)]*)\s*\)$/i;
const HSL_COLOR = /^hsla?\(\s*([^)]*)\s*\)$/i;
const FONT_PART = /^(?:"[^"\\\r\n;{}():]+"|'[^'\\\r\n;{}():]+'|[\p{L}\p{N} _-]+)$/u;

function isByte(value: string): boolean {
  return /^\d{1,3}$/.test(value) && Number(value) <= 255;
}

function isAlpha(value: string): boolean {
  if (/^(?:100|\d{1,2})(?:\.\d+)?%$/.test(value)) return Number(value.slice(0, -1)) <= 100;
  return /^(?:0(?:\.\d+)?|1(?:\.0+)?)$/.test(value);
}

function isPercentage(value: string): boolean {
  return /^(?:100|\d{1,2})(?:\.\d+)?%$/.test(value) && Number(value.slice(0, -1)) <= 100;
}

function isSafeColor(value: string): boolean {
  if (HEX_COLOR.test(value)) return true;
  const rgb = value.match(RGB_COLOR);
  if (rgb) {
    const parts = rgb[1]!.split(',').map((part) => part.trim());
    const expectedLength = value.toLowerCase().startsWith('rgba') ? 4 : 3;
    return parts.length === expectedLength
      && parts.slice(0, 3).every(isByte)
      && (expectedLength === 3 || isAlpha(parts[3]!));
  }
  const hsl = value.match(HSL_COLOR);
  if (hsl) {
    const parts = hsl[1]!.split(',').map((part) => part.trim());
    const expectedLength = value.toLowerCase().startsWith('hsla') ? 4 : 3;
    return parts.length === expectedLength
      && /^\d{1,3}(?:\.\d+)?$/.test(parts[0]!)
      && Number(parts[0]) <= 360
      && isPercentage(parts[1]!)
      && isPercentage(parts[2]!)
      && (expectedLength === 3 || isAlpha(parts[3]!));
  }
  return false;
}

function isSafeFontFamily(value: string): boolean {
  if (value.length === 0 || value.length > 200 || /[\u0000-\u001f\u007f\\]/.test(value)) return false;
  return value.split(',').every((part) => FONT_PART.test(part.trim()) && part.trim().length > 0);
}

function invalidThemeValue(name: string): never {
  throw new TypeError(`CORPTCHA_INVALID_THEME_VALUE:${name}`);
}

export function parseTheme(theme: WidgetTheme = {}): ParsedTheme {
  const mode = theme.mode ?? 'auto';
  if (mode !== 'light' && mode !== 'dark' && mode !== 'auto') invalidThemeValue('mode');
  const variables: Partial<Record<ThemeVariableName, string>> = {};

  for (const [name, variable] of Object.entries(COLOR_VARIABLES) as [keyof typeof COLOR_VARIABLES, ThemeVariableName][]) {
    const value = theme[name];
    if (value === undefined) continue;
    if (!isSafeColor(value)) invalidThemeValue(name);
    variables[variable] = value;
  }

  if (theme.borderRadius !== undefined) {
    if (!Number.isFinite(theme.borderRadius) || theme.borderRadius < 0 || theme.borderRadius > 16) {
      throw new RangeError('CORPTCHA_INVALID_THEME_RADIUS');
    }
    variables['--cpt-radius'] = `${theme.borderRadius}px`;
  }

  if (theme.fontFamily !== undefined) {
    if (!isSafeFontFamily(theme.fontFamily)) invalidThemeValue('fontFamily');
    variables['--cpt-font'] = theme.fontFamily;
  }

  return Object.freeze({ mode, variables: Object.freeze(variables) });
}

