import { BRAND_STYLES, createBrandLockup } from '../brand.js';
import { renderPowOverlay, type PowOverlayHandle, type PowRevealResult } from '../pow-overlay.js';
import { COMPONENT_STYLES, HOST_RESET, SPATIAL_STYLES } from '../styles.js';
import type { SpatialChallengeData } from '../types.js';

export type { SpatialChallengeData } from '../types.js';

export interface SpatialPoint {
  x: number;
  y: number;
}

export interface PreparedSpatialMedia {
  readonly data: SpatialChallengeData;
  readonly image: HTMLImageElement;
}

export interface SpatialRendererOptions {
  data: SpatialChallengeData;
  restoreFocus: HTMLElement;
  onConfirm(point: SpatialPoint, event: Event, pow: PowRevealResult): void;
  onRefresh(): void;
  onClose(): void;
  onMediaError?(error: Error): void;
}

export interface SpatialChallengeView {
  readonly ready: Promise<void>;
  setBusy(busy: boolean): void;
  setRefreshing(refreshing: boolean): void;
  prepareMedia(data: SpatialChallengeData, signal?: AbortSignal): Promise<PreparedSpatialMedia>;
  replaceMedia(media: PreparedSpatialMedia): void;
  replace(data: SpatialChallengeData, signal?: AbortSignal): Promise<void>;
  showSuccess(): void;
  startLeaving(): void;
  focus(): void;
  close(): Promise<void>;
  destroy(): void;
}

let dialogSequence = 0;

function createIconButton(label: string, paths: readonly string[]): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'cpt-icon-button';
  button.setAttribute('aria-label', label);
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  for (const data of paths) {
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', data);
    svg.append(path);
  }
  button.append(svg);
  return button;
}

function loadingMask(): HTMLDivElement {
  const mask = document.createElement('div');
  mask.className = 'cpt-media-refresh';
  const spinner = document.createElement('span');
  spinner.className = 'cpt-spinner';
  spinner.setAttribute('aria-hidden', 'true');
  mask.append(spinner);
  return mask;
}

function clamp(value: number): number {
  return Math.min(1, Math.max(0, value));
}

export function renderSpatial(container: HTMLElement | ShadowRoot, options: SpatialRendererOptions): SpatialChallengeView {
  const style = document.createElement('style');
  style.textContent = `${HOST_RESET}${COMPONENT_STYLES}${BRAND_STYLES}${SPATIAL_STYLES}`;
  const overlay = document.createElement('div');
  overlay.className = 'cpt-overlay';
  const dialog = document.createElement('section');
  dialog.className = 'cpt-modal';
  dialog.setAttribute('role', 'dialog');
  dialog.setAttribute('aria-modal', 'true');
  const title = document.createElement('h2');
  title.id = `cpt-spatial-title-${++dialogSequence}`;
  title.className = 'cpt-title';
  title.textContent = '安全验证';
  dialog.setAttribute('aria-labelledby', title.id);
  const header = document.createElement('header');
  header.className = 'cpt-header';
  header.append(title);
  const body = document.createElement('div');
  body.className = 'cpt-body';
  const stage = document.createElement('div');
  stage.className = 'cpt-spatial-stage';
  const crosshair = document.createElement('span');
  crosshair.className = 'cpt-spatial-crosshair';
  crosshair.style.left = '50%';
  crosshair.style.top = '50%';
  crosshair.hidden = true;
  const success = document.createElement('div');
  success.className = 'cpt-success';
  success.setAttribute('role', 'status');
  success.setAttribute('aria-live', 'polite');
  const successIcon = document.createElement('span');
  successIcon.className = 'cpt-success-icon';
  successIcon.textContent = '✓';
  success.append(successIcon, document.createTextNode('验证通过'));
  const actions = document.createElement('div');
  actions.className = 'cpt-spatial-actions';
  const confirm = document.createElement('button');
  confirm.type = 'button';
  confirm.className = 'cpt-spatial-confirm';
  confirm.textContent = '确认';
  confirm.disabled = true;
  actions.append(confirm);
  body.append(stage, actions);
  const footer = document.createElement('footer');
  footer.className = 'cpt-footer';
  const toolbar = document.createElement('div');
  toolbar.className = 'cpt-toolbar';
  const close = createIconButton('关闭挑战', ['M6 6l12 12', 'M18 6 6 18']);
  const refresh = createIconButton('刷新挑战', ['M20 11a8 8 0 1 0-2.3 5.7', 'M20 4v7h-7']);
  toolbar.append(close, refresh);
  footer.append(toolbar, createBrandLockup('footer'));
  dialog.append(header, body, footer);
  overlay.append(dialog);
  container.append(style, overlay);

  let destroyed = false;
  let busy = false;
  let refreshing = false;
  let leaving = false;
  let selected: SpatialPoint | undefined;
  let selectedEvent: Event | undefined;
  let keyboardPoint: SpatialPoint = { x: 0.5, y: 0.5 };
  let currentGrid: HTMLElement | undefined;
  let replacementGeneration = 0;
  let closeTimer: ReturnType<typeof setTimeout> | undefined;
  let powOverlay: PowOverlayHandle | undefined;
  let powReveal: PowRevealResult | undefined;

  const updateMarker = (): void => {
    stage.querySelector('.cpt-spatial-marker')?.remove();
    if (!selected) return;
    const marker = document.createElement('span');
    marker.className = 'cpt-spatial-marker';
    marker.style.left = `${selected.x * 100}%`;
    marker.style.top = `${selected.y * 100}%`;
    stage.append(marker);
  };
  const updateControls = (): void => {
    confirm.disabled = busy || refreshing || selected === undefined || !powReveal;
    close.disabled = busy || refreshing || !powReveal;
    refresh.disabled = busy || refreshing || !powReveal;
    dialog.setAttribute('aria-busy', String(busy || refreshing));
  };
  const mountPowOverlay = (data: SpatialChallengeData): void => {
    powOverlay?.destroy();
    powOverlay = undefined;
    powReveal = undefined;
    powOverlay = renderPowOverlay(stage, {
      imageUrl: data.image,
      pow: data.pow,
      onRevealed: (result) => {
        powReveal = result;
        updateControls();
      },
      onError: (error) => {
        if (!destroyed) options.onMediaError?.(error);
      },
    });
    const grid = powOverlay.element;
    grid.style.cursor = 'crosshair';
    currentGrid?.removeEventListener('pointerdown', onPointerDown);
    currentGrid?.removeEventListener('keydown', onImageKeyDown);
    currentGrid = grid;
    grid.addEventListener('pointerdown', onPointerDown);
    grid.addEventListener('keydown', onImageKeyDown);
    updateControls();
  };
  const select = (point: SpatialPoint, event: Event): void => {
    if (busy || refreshing || destroyed || !powReveal) return;
    selected = { x: clamp(point.x), y: clamp(point.y) };
    selectedEvent = event;
    keyboardPoint = selected;
    updateMarker();
    updateControls();
  };
  const pointFromPointer = (event: PointerEvent): SpatialPoint | undefined => {
    if (!currentGrid) return undefined;
    const rect = currentGrid.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return undefined;
    return { x: clamp((event.clientX - rect.left) / rect.width), y: clamp((event.clientY - rect.top) / rect.height) };
  };
  const prepareMedia = (data: SpatialChallengeData, signal?: AbortSignal): Promise<PreparedSpatialMedia> => {
    if (!data.image.startsWith('data:image/png;base64,') || data.width !== 600 || data.height !== 375) return Promise.reject(new Error('CORPTCHA_INVALID_SPATIAL_IMAGE'));
    if (signal?.aborted) return Promise.reject(new DOMException('Aborted', 'AbortError'));
    const image = document.createElement('img');
    image.src = data.image;
    image.alt = '空间图形验证图片';
    image.tabIndex = 0;
    image.hidden = true;
    // 完整乱序图永远不被整体展示：原图仅作加载探针与占位，视觉由 div 网格切分替代
    image.style.display = 'none';
    stage.append(image);
    return new Promise((resolve, reject) => {
      const cleanup = (): void => {
        image.removeEventListener('load', onLoad);
        image.removeEventListener('error', onError);
        signal?.removeEventListener('abort', onAbort);
      };
      const onLoad = (): void => { cleanup(); image.style.opacity = '0'; resolve({ data, image }); };
      const onError = (): void => { cleanup(); image.remove(); reject(new Error('CORPTCHA_INVALID_SPATIAL_IMAGE')); };
      const onAbort = (): void => { cleanup(); image.remove(); reject(new DOMException('Aborted', 'AbortError')); };
      image.addEventListener('load', onLoad, { once: true });
      image.addEventListener('error', onError, { once: true });
      signal?.addEventListener('abort', onAbort, { once: true });
    });
  };
  const replaceMedia = (media: PreparedSpatialMedia): void => {
    if (destroyed) return;
    media.image.style.opacity = '0';
    stage.style.aspectRatio = `${media.data.width} / ${media.data.height}`;
    selected = undefined;
    selectedEvent = undefined;
    keyboardPoint = { x: 0.5, y: 0.5 };
    crosshair.style.left = '50%';
    crosshair.style.top = '50%';
    crosshair.hidden = true;
    stage.replaceChildren(media.image, crosshair, success);
    mountPowOverlay(media.data);
  };
  function onPointerDown(event: PointerEvent): void {
    const point = pointFromPointer(event);
    if (point) select(point, event);
  }
  function onImageKeyDown(event: KeyboardEvent): void {
    if (event.key === 'Tab' && selected && !event.shiftKey) {
      event.preventDefault();
      confirm.focus();
      return;
    }
    const movement: Readonly<Record<string, SpatialPoint>> = {
      ArrowLeft: { x: -0.05, y: 0 },
      ArrowRight: { x: 0.05, y: 0 },
      ArrowUp: { x: 0, y: -0.05 },
      ArrowDown: { x: 0, y: 0.05 },
    };
    if (event.key === 'Enter') {
      event.preventDefault();
      select(keyboardPoint, event);
      return;
    }
    const delta = movement[event.key];
    if (!delta || busy || refreshing) return;
    event.preventDefault();
    keyboardPoint = { x: clamp(keyboardPoint.x + delta.x), y: clamp(keyboardPoint.y + delta.y) };
    crosshair.style.left = `${keyboardPoint.x * 100}%`;
    crosshair.style.top = `${keyboardPoint.y * 100}%`;
    crosshair.hidden = false;
  }
  const cleanup = (): void => {
    if (destroyed) return;
    destroyed = true;
    replacementGeneration += 1;
    if (closeTimer !== undefined) clearTimeout(closeTimer);
    powOverlay?.destroy();
    powOverlay = undefined;
    currentGrid?.removeEventListener('pointerdown', onPointerDown);
    currentGrid?.removeEventListener('keydown', onImageKeyDown);
    overlay.removeEventListener('keydown', onOverlayKeyDown);
    overlay.removeEventListener('click', onOverlayClick);
    confirm.removeEventListener('click', onConfirm);
    close.removeEventListener('click', onClose);
    refresh.removeEventListener('click', onRefresh);
    style.remove();
    overlay.remove();
  };
  const closeDialog = (): Promise<void> => {
    if (destroyed || busy || refreshing || leaving || !powReveal) return Promise.resolve();
    leaving = true;
    overlay.classList.add('cpt-overlay--leaving');
    return new Promise((resolve) => {
      closeTimer = setTimeout(() => {
        cleanup();
        options.onClose();
        options.restoreFocus.focus();
        resolve();
      }, 160);
    });
  };
  const onConfirm = (event: MouseEvent): void => {
    if (selected && selectedEvent && !busy && !refreshing && powReveal) options.onConfirm(selected, selectedEvent ?? event, powReveal);
  };
  const onClose = (): void => { void closeDialog(); };
  const onRefresh = (): void => { if (!busy && !refreshing && !leaving && powReveal) options.onRefresh(); };
  const onOverlayClick = (event: MouseEvent): void => { if (event.target === overlay) void closeDialog(); };
  const onOverlayKeyDown = (event: KeyboardEvent): void => {
    if (event.key === 'Escape') {
      event.preventDefault();
      void closeDialog();
    }
  };

  overlay.addEventListener('keydown', onOverlayKeyDown);
  overlay.addEventListener('click', onOverlayClick);
  confirm.addEventListener('click', onConfirm);
  close.addEventListener('click', onClose);
  refresh.addEventListener('click', onRefresh);
  stage.style.aspectRatio = `${options.data.width} / ${options.data.height}`;
  const mask = loadingMask();
  stage.append(mask);
  const initialMedia = prepareMedia(options.data);
  const ready = initialMedia.then((media) => {
    if (!destroyed) replaceMedia(media);
  }).catch((error: unknown) => {
    mask.remove();
    const normalized = error instanceof Error ? error : new Error('CORPTCHA_INVALID_SPATIAL_IMAGE');
    if (!destroyed) options.onMediaError?.(normalized);
    throw normalized;
  });

  return {
    ready,
    setBusy(value) {
      if (destroyed) return;
      busy = value;
      confirm.replaceChildren();
      if (value) confirm.append(loadingMask().querySelector('.cpt-spinner')!);
      confirm.append(document.createTextNode(value ? '验证中' : '确认'));
      updateControls();
    },
    setRefreshing(value) {
      if (destroyed) return;
      refreshing = value;
      stage.querySelector('.cpt-media-refresh')?.remove();
      if (value) stage.append(loadingMask());
      updateControls();
    },
    prepareMedia,
    replaceMedia,
    async replace(data, signal) {
      const generation = ++replacementGeneration;
      const media = await prepareMedia(data, signal);
      if (!destroyed && generation === replacementGeneration) replaceMedia(media);
    },
    showSuccess() {
      if (!destroyed) dialog.classList.add('cpt-modal--success');
    },
    startLeaving() {
      if (destroyed) return;
      leaving = true;
      overlay.classList.add('cpt-overlay--leaving');
    },
    focus: () => { if (!destroyed) currentGrid?.focus(); },
    close: closeDialog,
    destroy: cleanup,
  };
}
