import { BRAND_STYLES, createBrandLockup } from '../brand.js';
import { clamp01 } from '../coordinates.js';
import { prepareImages, type ImagePreparation } from '../media.js';
import { PointerTelemetryCollector, type PointerDrag } from '../pointer-telemetry.js';
import { renderPowOverlay, type PowOverlayHandle, type PowRevealResult } from '../pow-overlay.js';
import type { PowParameters } from '../pow.js';
import { COMPONENT_STYLES, HOST_RESET, SPATIAL_STYLES, SUCCESS_FEEDBACK_STYLES } from '../styles.js';

export interface SliderChallengeData {
  schemaVersion: 1;
  interactionNonce: string;
  backgroundImage: string;
  pieceImage: string;
  imageWidth: number;
  imageHeight: number;
  pieceWidth: number;
  pieceHeight: number;
  pieceY: number;
  trackStartX: number;
  pow: PowParameters;
}

export interface SliderResponse {
  schemaVersion: 1;
  interactionNonce: string;
  finalPosition: number;
  powNonce: number;
}

export type SliderTelemetry = { schemaVersion: 1; mode: 'pointer'; drag: PointerDrag; powActualMs: number };

export interface SliderRendererOptions {
  data: SliderChallengeData;
  restoreFocus: HTMLElement;
  onSubmit(response: SliderResponse, telemetry: SliderTelemetry): void;
  onRefresh(): void;
  onClose(): void;
  onMediaError?(error: Error): void;
}

export interface SliderRendererHandle {
  readonly ready: Promise<void>;
  setBusy(busy: boolean): void;
  setRefreshing(refreshing: boolean): void;
  lock(): void;
  focus(): void;
  destroy(): void;
}

const STYLES = '.cpt-slider{display:grid;gap:10px}.cpt-slider-stage{position:relative;width:100%;overflow:hidden;border:1px solid var(--cpt-border);border-radius:6px;background:var(--cpt-stage);touch-action:none}.cpt-slider-background{width:100%;height:100%;object-fit:contain}.cpt-slider-piece{position:absolute;z-index:1;height:auto;pointer-events:none;transition:filter .12s ease}.cpt-slider-handle{position:relative;display:grid;min-width:44px;min-height:44px;width:44px;height:44px;place-items:center;border:0;border-radius:8px;background:var(--cpt-accent);color:var(--cpt-button-text);touch-action:none;cursor:grab;transition:box-shadow .12s ease,scale .12s ease}.cpt-slider[data-picked="true"] .cpt-slider-handle{cursor:grabbing;scale:1.03;box-shadow:0 6px 14px color-mix(in srgb,var(--cpt-accent) 28%,transparent)}.cpt-slider[data-picked="true"] .cpt-slider-piece{filter:drop-shadow(0 5px 5px rgba(15,23,42,.24))}.cpt-slider[data-magnetic="true"] .cpt-slider-handle{box-shadow:0 0 0 3px color-mix(in srgb,var(--cpt-success) 18%,transparent)}.cpt-slider[aria-busy="true"]{opacity:.65}@media (prefers-reduced-motion:reduce){.cpt-slider-piece,.cpt-slider-handle{transition:none}.cpt-slider[data-picked="true"] .cpt-slider-handle{scale:none}}';

function rounded(value: number): number {
  return Number(clamp01(value).toFixed(4));
}

function iconButton(label: string, paths: readonly string[]): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'cpt-icon-button';
  button.setAttribute('aria-label', label);
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  for (const value of paths) {
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', value);
    svg.append(path);
  }
  button.append(svg);
  return button;
}

let dialogSequence = 0;

export function renderSlider(container: HTMLElement | ShadowRoot, options: SliderRendererOptions): SliderRendererHandle {
  const style = document.createElement('style');
  style.textContent = `${HOST_RESET}${COMPONENT_STYLES}${BRAND_STYLES}${SPATIAL_STYLES}${SUCCESS_FEEDBACK_STYLES}${STYLES}`;
  const overlay = document.createElement('div');
  overlay.className = 'cpt-overlay';
  const dialog = document.createElement('section');
  dialog.className = 'cpt-modal';
  dialog.setAttribute('role', 'dialog');
  dialog.setAttribute('aria-modal', 'true');
  const title = document.createElement('h2');
  title.id = `cpt-slider-title-${++dialogSequence}`;
  title.className = 'cpt-title';
  title.textContent = '安全验证';
  dialog.setAttribute('aria-labelledby', title.id);
  const header = document.createElement('header');
  header.className = 'cpt-header';
  header.append(title);
  const body = document.createElement('div');
  body.className = 'cpt-body';
  const root = document.createElement('section');
  root.className = 'cpt-slider';
  const stage = document.createElement('div');
  stage.className = 'cpt-slider-stage';
  stage.style.aspectRatio = `${options.data.imageWidth} / ${options.data.imageHeight}`;
  const handle = document.createElement('button');
  handle.type = 'button';
  handle.className = 'cpt-slider-handle';
  handle.style.minWidth = '44px';
  handle.style.minHeight = '44px';
  handle.setAttribute('aria-label', '拖动拼图滑块');
  handle.textContent = '→';
  root.append(stage, handle);
  body.append(root);
  const footer = document.createElement('footer');
  footer.className = 'cpt-footer';
  const toolbar = document.createElement('div');
  toolbar.className = 'cpt-toolbar';
  const close = iconButton('关闭挑战', ['M6 6l12 12', 'M18 6 6 18']);
  const refresh = iconButton('刷新挑战', ['M20 11a8 8 0 1 0-2.3 5.7', 'M20 4v7h-7']);
  toolbar.append(close, refresh);
  footer.append(toolbar, createBrandLockup('footer'));
  dialog.append(header, body, footer);
  overlay.append(dialog);
  container.append(style, overlay);

  let destroyed = false;
  let locked = false;
  let busy = false;
  let refreshing = false;
  let leaving = false;
  let position = rounded(options.data.trackStartX);
  let grabOffset = 0;
  let preparation: ImagePreparation | undefined;
  let collector: PointerTelemetryCollector | undefined;
  let background: HTMLImageElement | undefined;
  let piece: HTMLImageElement | undefined;
  let powOverlay: PowOverlayHandle | undefined;
  let powReveal: PowRevealResult | undefined;
  let closeTimer: ReturnType<typeof setTimeout> | undefined;

  const pieceWidthCss = (): number => stage.getBoundingClientRect().width * options.data.pieceWidth / options.data.imageWidth;
  const availableWidth = (): number => Math.max(1, stage.getBoundingClientRect().width - pieceWidthCss());
  const renderPosition = (): void => {
    if (piece) {
      piece.style.left = `${position * 100}%`;
      piece.style.width = `${options.data.pieceWidth / options.data.imageWidth * 100}%`;
      piece.style.transform = `translateX(${-position * 100}%)`;
    }
    handle.style.marginLeft = `calc(${position * 100}% - ${position * 44}px)`;
  };
  const update = (): void => {
    const disabled = destroyed || locked || busy || refreshing || !powReveal;
    handle.disabled = disabled;
    close.disabled = disabled;
    refresh.disabled = disabled;
    root.setAttribute('aria-busy', String(busy || refreshing));
    dialog.setAttribute('aria-busy', String(busy || refreshing));
  };
  const abortDrag = (): void => {
    collector?.abort();
    collector = undefined;
    root.dataset.picked = 'false';
    root.dataset.magnetic = 'false';
    handle.style.cursor = 'grab';
  };
  const submitPointer = (drag: PointerDrag): void => {
    if (destroyed || locked || busy || refreshing || !powReveal) return;
    options.onSubmit(
      { schemaVersion: 1, interactionNonce: options.data.interactionNonce, finalPosition: position, powNonce: powReveal.nonce },
      { schemaVersion: 1, mode: 'pointer', drag, powActualMs: powReveal.actualMs },
    );
  };
  const onPointerDown = (event: PointerEvent): void => {
    if (handle.disabled) return;
    const stageRect = stage.getBoundingClientRect();
    grabOffset = event.clientX - stageRect.left - position * availableWidth();
    const next = new PointerTelemetryCollector({ target: handle, rect: () => {
      const rect = stage.getBoundingClientRect();
      const width = availableWidth();
      return { left: rect.left + grabOffset, top: rect.top, width, height: rect.height };
    } });
    if (!next.start(event)) return;
    collector = next;
    root.dataset.picked = 'true';
    handle.style.cursor = 'grabbing';
  };
  const onPointerMove = (event: PointerEvent): void => {
    if (!collector?.move(event)) return;
    position = rounded((event.clientX - stage.getBoundingClientRect().left - grabOffset) / availableWidth());
    root.dataset.magnetic = String(position >= 0.96);
    renderPosition();
  };
  const onPointerUp = (event: PointerEvent): void => {
    const active = collector;
    if (!active) return;
    position = rounded((event.clientX - stage.getBoundingClientRect().left - grabOffset) / availableWidth());
    renderPosition();
    const drag = active.finish(event, 'slider-drag');
    collector = undefined;
    root.dataset.picked = 'false';
    root.dataset.magnetic = 'false';
    handle.style.cursor = 'grab';
    if (drag) submitPointer(drag);
  };
  const onPointerCancel = (event: PointerEvent): void => {
    collector?.cancel(event);
    collector = undefined;
    root.dataset.picked = 'false';
    root.dataset.magnetic = 'false';
    handle.style.cursor = 'grab';
  };
  const onBlur = (): void => abortDrag();
  const onVisibility = (): void => { if (document.visibilityState === 'hidden') abortDrag(); };
  const cleanup = (restore: boolean): void => {
    if (destroyed) return;
    destroyed = true;
    abortDrag();
    if (closeTimer !== undefined) clearTimeout(closeTimer);
    powOverlay?.destroy();
    powOverlay = undefined;
    preparation?.destroy();
    handle.removeEventListener('pointerdown', onPointerDown);
    handle.removeEventListener('pointermove', onPointerMove);
    handle.removeEventListener('pointerup', onPointerUp);
    handle.removeEventListener('pointercancel', onPointerCancel);
    close.removeEventListener('click', onClose);
    refresh.removeEventListener('click', onRefresh);
    overlay.removeEventListener('keydown', onOverlayKeyDown);
    overlay.removeEventListener('click', onOverlayClick);
    window.removeEventListener('blur', onBlur);
    document.removeEventListener('visibilitychange', onVisibility);
    overlay.remove();
    style.remove();
    if (restore) options.restoreFocus.focus();
  };
  const closeDialog = (): void => {
    if (destroyed || busy || refreshing || leaving) return;
    leaving = true;
    overlay.classList.add('cpt-overlay--leaving');
    closeTimer = setTimeout(() => {
      cleanup(true);
      options.onClose();
    }, 160);
  };
  function onClose(): void { closeDialog(); }
  function onRefresh(): void { if (!busy && !refreshing && !leaving) options.onRefresh(); }
  function onOverlayKeyDown(event: KeyboardEvent): void {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    closeDialog();
  }
  function onOverlayClick(event: MouseEvent): void { if (event.target === overlay) closeDialog(); }

  handle.addEventListener('pointerdown', onPointerDown);
  handle.addEventListener('pointermove', onPointerMove);
  handle.addEventListener('pointerup', onPointerUp);
  handle.addEventListener('pointercancel', onPointerCancel);
  close.addEventListener('click', onClose);
  refresh.addEventListener('click', onRefresh);
  overlay.addEventListener('keydown', onOverlayKeyDown);
  overlay.addEventListener('click', onOverlayClick);
  window.addEventListener('blur', onBlur);
  document.addEventListener('visibilitychange', onVisibility);

  preparation = prepareImages([options.data.backgroundImage, options.data.pieceImage]);
  [background, piece] = preparation.images as [HTMLImageElement, HTMLImageElement];
  background.className = 'cpt-slider-background';
  background.alt = '';
  background.hidden = true;
  piece.className = 'cpt-slider-piece';
  piece.alt = '';
  piece.hidden = true;
  piece.style.top = `${options.data.pieceY / options.data.imageHeight * 100}%`;
  stage.append(background, piece);
  powOverlay = renderPowOverlay(stage, {
    imageUrl: options.data.backgroundImage,
    pow: options.data.pow,
    onRevealed: (result) => {
      powReveal = result;
      update();
    },
    onError: (error) => {
      if (!destroyed) options.onMediaError?.(error);
    },
  });
  update();
  const ready = preparation.ready.then((images) => {
    if (destroyed) return;
    [background, piece] = images as [HTMLImageElement, HTMLImageElement];
    // 背景不再整体展示：由 div 网格切分显示
    background.style.opacity = '0';
    piece.hidden = false;
    renderPosition();
  });
  void ready.catch((error: unknown) => {
    if (!destroyed) options.onMediaError?.(error instanceof Error ? error : new Error('CORPTCHA_MEDIA_ERROR'));
  });

  return {
    ready,
    setBusy: (value) => { busy = value; update(); },
    setRefreshing: (value) => { refreshing = value; if (value) abortDrag(); update(); },
    lock: () => { locked = true; abortDrag(); update(); },
    focus: () => handle.focus(),
    destroy: () => cleanup(true),
  };
}
