export type EffectiveTheme = 'light' | 'dark';

export interface ThemeController {
  readonly theme: EffectiveTheme;
  destroy(): void;
}

type ThemeMode = EffectiveTheme | 'auto';

function readPageTheme(root: Element): EffectiveTheme | undefined {
  try {
    const view = root.ownerDocument.defaultView;
    if (!view?.getComputedStyle) return undefined;
    const colorScheme = view.getComputedStyle(root).colorScheme.trim().toLowerCase();
    if (colorScheme === 'light' || colorScheme === 'dark') return colorScheme;
  } catch {
    return undefined;
  }
  return undefined;
}

export function createThemeController(
  mode: ThemeMode,
  root: Element,
  onChange: (theme: EffectiveTheme) => void,
): ThemeController {
  if (mode !== 'auto') return { theme: mode, destroy() {} };

  const pageTheme = readPageTheme(root);
  if (pageTheme) return { theme: pageTheme, destroy() {} };

  const view = root.ownerDocument.defaultView;
  if (!view || typeof view.matchMedia !== 'function') return { theme: 'light', destroy() {} };

  let media: MediaQueryList;
  try {
    media = view.matchMedia('(prefers-color-scheme: dark)');
  } catch {
    return { theme: 'light', destroy() {} };
  }
  if (typeof media.addEventListener !== 'function' || typeof media.removeEventListener !== 'function') {
    return { theme: 'light', destroy() {} };
  }

  let theme: EffectiveTheme = media.matches ? 'dark' : 'light';
  let destroyed = false;
  const handleChange = (event: MediaQueryListEvent): void => {
    if (destroyed) return;
    const next = event.matches ? 'dark' : 'light';
    if (next === theme) return;
    theme = next;
    onChange(next);
  };
  media.addEventListener('change', handleChange);

  return {
    get theme() { return theme; },
    destroy() {
      if (destroyed) return;
      destroyed = true;
      media.removeEventListener('change', handleChange);
    },
  };
}
