import { CORPTCHA_LOGO_DATA_URL } from './assets/corptcha-logo.js';
import { CORPTCHA_LOGO_DARK_DATA_URL } from './assets/corptcha-logo-dark.js';

export type BrandLockupSize = 'compact' | 'footer';

export const BRAND_STYLES = '.cpt-brand-lockup{display:inline-flex;flex:0 0 auto;align-items:center;line-height:1}.cpt-brand-logo{display:block;flex:none;height:var(--cpt-brand-logo-height);width:auto}.cpt-brand-lockup--compact{--cpt-brand-logo-height:18px;margin-left:12px}.cpt-brand-lockup--footer{--cpt-brand-logo-height:14px;padding-right:3px}.cpt-brand-logo--dark{display:none}:host([data-theme="dark"]) .cpt-brand-logo--light{display:none}:host([data-theme="dark"]) .cpt-brand-logo--dark{display:block}';

export function createBrandLockup(size?: BrandLockupSize): HTMLSpanElement {
  const lockup = document.createElement('span');
  lockup.className = `cpt-brand-lockup${size ? ` cpt-brand-lockup--${size}` : ''}`;
  lockup.setAttribute('aria-hidden', 'true');
  const lightLogo = document.createElement('img');
  lightLogo.className = 'cpt-brand-logo cpt-brand-logo--light';
  lightLogo.src = CORPTCHA_LOGO_DATA_URL;
  lightLogo.alt = 'Corptcha';
  const darkLogo = document.createElement('img');
  darkLogo.className = 'cpt-brand-logo cpt-brand-logo--dark';
  darkLogo.src = CORPTCHA_LOGO_DARK_DATA_URL;
  darkLogo.alt = 'Corptcha';
  lockup.append(lightLogo, darkLogo);
  return lockup;
}
