import type { WidgetState, WidgetStateName } from './types.js';

const TRANSITIONS: Readonly<Record<WidgetStateName, readonly WidgetStateName[]>> = {
  idle: ['analyzing', 'destroyed'],
  analyzing: ['idle', 'ready', 'success', 'error', 'destroyed'],
  ready: ['idle', 'submitting', 'error', 'destroyed'],
  submitting: ['idle', 'success', 'error', 'destroyed'],
  success: ['idle', 'expired', 'destroyed'],
  error: ['idle', 'analyzing', 'ready', 'destroyed'],
  expired: ['idle', 'analyzing', 'destroyed'],
  destroyed: [],
};

export interface StateController {
  getSnapshot(): WidgetState;
  transition(next: WidgetState): WidgetState;
}

export function createStateController(onChange?: (state: WidgetState) => void): StateController {
  let current: WidgetState = Object.freeze({ name: 'idle' });

  return {
    getSnapshot: () => current,
    transition(next) {
      if (current.name === 'destroyed' && next.name === 'destroyed') return current;
      if (!TRANSITIONS[current.name].includes(next.name)) {
        throw new Error(`CORPTCHA_INVALID_STATE_TRANSITION:${current.name}:${next.name}`);
      }
      current = Object.freeze({ ...next }) as WidgetState;
      onChange?.(current);
      return current;
    },
  };
}
