export interface Point {
  x: number;
  y: number;
}

export interface CoordinateRect {
  left: number;
  top: number;
  width: number;
  height: number;
}

export interface CoordinateSize {
  width: number;
  height: number;
}

export function clamp01(value: number): number {
  return Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0;
}

function validate(rect: CoordinateRect, size: CoordinateSize): void {
  if (![rect.left, rect.top, rect.width, rect.height, size.width, size.height].every(Number.isFinite)
    || rect.width <= 0 || rect.height <= 0 || size.width <= 0 || size.height <= 0) {
    throw new Error('CORPTCHA_INVALID_COORDINATE_SPACE');
  }
}

export function cssPointToLogical(point: Point, rect: CoordinateRect, size: CoordinateSize): Point {
  validate(rect, size);
  return {
    x: clamp01((point.x - rect.left) / rect.width) * size.width,
    y: clamp01((point.y - rect.top) / rect.height) * size.height,
  };
}

export function logicalPointToCss(point: Point, rect: CoordinateRect, size: CoordinateSize): Point {
  validate(rect, size);
  return {
    x: rect.left + clamp01(point.x / size.width) * rect.width,
    y: rect.top + clamp01(point.y / size.height) * rect.height,
  };
}

export function normalizeLogicalPoint(point: Point, size: CoordinateSize): Point {
  validate({ left: 0, top: 0, width: size.width, height: size.height }, size);
  return { x: clamp01(point.x / size.width), y: clamp01(point.y / size.height) };
}
