const STREAM_HEADER_BYTES = 13;
const FRAME_HEADER_BYTES = 12;
const MAX_WIDTH = 1280;
const MAX_HEIGHT = 720;
const MIN_FPS = 15;
const MAX_FPS = 60;
const MAX_FRAMES = 480;

export const GHOST_STREAM_MAX_BYTES = 3 * 1024 * 1024;

export interface GhostStreamFrame {
  readonly index: number;
  readonly presentationTimeMs: number;
  readonly pixels: Uint8Array;
}

export interface DecodedGhostStream {
  readonly width: number;
  readonly height: number;
  readonly fps: number;
  readonly frameCount: number;
  readonly inverted: boolean;
  readonly frames: readonly GhostStreamFrame[];
  writeFrameRgba(frameIndex: number, target: Uint8ClampedArray): void;
}

export interface GhostStreamPlayerOptions {
  scheduleFrame?: (callback: FrameRequestCallback) => number;
  cancelFrame?: (handle: number) => void;
  visibilityTarget?: Document;
}

function invalidStream(): never {
  throw new Error('CORPTCHA_INVALID_GHOST_STREAM');
}

function normalizeBytes(value: Uint8Array | ArrayBuffer): Uint8Array {
  const bytes = value instanceof Uint8Array ? value : new Uint8Array(value);
  if (bytes.byteLength > GHOST_STREAM_MAX_BYTES) throw new Error('CORPTCHA_GHOST_STREAM_TOO_LARGE');
  return bytes;
}

export function decodeGhostStream(value: Uint8Array | ArrayBuffer): DecodedGhostStream {
  const bytes = normalizeBytes(value);
  if (bytes.byteLength < STREAM_HEADER_BYTES) invalidStream();
  if (bytes[0] !== 0x47 || bytes[1] !== 0x48 || bytes[2] !== 0x53 || bytes[3] !== 0x54 || bytes[4] !== 1) invalidStream();
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const width = view.getUint16(5);
  const height = view.getUint16(7);
  const fps = bytes[9]!;
  const frameCount = view.getUint16(10);
  const invert = bytes[12]!;
  if (width < 1 || width > MAX_WIDTH || height < 1 || height > MAX_HEIGHT) invalidStream();
  if (fps < MIN_FPS || fps > MAX_FPS || frameCount < 1 || frameCount > MAX_FRAMES || invert > 1) invalidStream();
  const frameBytes = Math.ceil(width * height / 8);
  const expectedLength = STREAM_HEADER_BYTES + frameCount * (FRAME_HEADER_BYTES + frameBytes);
  if (expectedLength !== bytes.byteLength) invalidStream();
  const frames: GhostStreamFrame[] = [];
  let offset = STREAM_HEADER_BYTES;
  for (let index = 0; index < frameCount; index += 1) {
    const frameIndex = view.getUint32(offset);
    const presentationTimeMs = view.getUint32(offset + 4);
    const payloadLength = view.getUint32(offset + 8);
    if (frameIndex !== index || presentationTimeMs !== Math.round(index * 1000 / fps) || payloadLength !== frameBytes) invalidStream();
    const payloadStart = offset + FRAME_HEADER_BYTES;
    frames.push({ index: frameIndex, presentationTimeMs, pixels: bytes.slice(payloadStart, payloadStart + frameBytes) });
    offset = payloadStart + frameBytes;
  }
  const inverted = invert === 1;
  return {
    width,
    height,
    fps,
    frameCount,
    inverted,
    frames,
    writeFrameRgba(frameIndex, target) {
      const frame = frames[frameIndex];
      const pixelCount = width * height;
      if (!frame || target.length !== pixelCount * 4) invalidStream();
      for (let pixel = 0; pixel < pixelCount; pixel += 1) {
        const bit = (frame.pixels[pixel >> 3]! >> (7 - (pixel & 7))) & 1;
        const value = (bit === 1) !== inverted ? 255 : 0;
        const targetIndex = pixel * 4;
        target[targetIndex] = value;
        target[targetIndex + 1] = value;
        target[targetIndex + 2] = value;
        target[targetIndex + 3] = 255;
      }
    },
  };
}

export class GhostStreamPlayer {
  private readonly scheduleFrame: (callback: FrameRequestCallback) => number;
  private readonly cancelFrame: (handle: number) => void;
  private readonly visibilityTarget: Document;
  private handle: number | undefined;
  private stream: DecodedGhostStream | undefined;
  private context: CanvasRenderingContext2D | undefined;
  private image: ImageData | undefined;
  private frameIndex = 0;
  private previousTime: number | undefined;
  private destroyed = false;

  constructor(private readonly canvas: HTMLCanvasElement, options: GhostStreamPlayerOptions = {}) {
    this.scheduleFrame = options.scheduleFrame ?? requestAnimationFrame.bind(globalThis);
    this.cancelFrame = options.cancelFrame ?? cancelAnimationFrame.bind(globalThis);
    this.visibilityTarget = options.visibilityTarget ?? document;
    this.visibilityTarget.addEventListener('visibilitychange', this.onVisibilityChange);
  }

  play(stream: DecodedGhostStream): void {
    if (this.destroyed) throw new Error('CORPTCHA_GHOST_PLAYER_DESTROYED');
    this.stop();
    const context = this.canvas.getContext('2d');
    if (!context) throw new Error('CORPTCHA_GHOST_PLAYBACK_UNAVAILABLE');
    this.canvas.width = stream.width;
    this.canvas.height = stream.height;
    this.context = context;
    this.image = context.createImageData(stream.width, stream.height);
    this.stream = stream;
    this.frameIndex = 0;
    this.previousTime = undefined;
    this.drawCurrentFrame();
    if (this.visibilityTarget.visibilityState !== 'hidden') this.schedule();
  }

  async playResponse(response: Response): Promise<void> {
    if (this.destroyed) throw new Error('CORPTCHA_GHOST_PLAYER_DESTROYED');
    if (!response.body) invalidStream();
    const reader = response.body.getReader();
    let bytes = new Uint8Array(0);
    let metadata: { width: number; height: number; fps: number; frameCount: number; inverted: boolean; frameBytes: number } | undefined;
    const frames: GhostStreamFrame[] = [];
    let offset = STREAM_HEADER_BYTES;
    let totalBytes = 0;
    let started = false;
    let resolveFirst: (() => void) | undefined;
    let rejectFirst: ((error: unknown) => void) | undefined;
    const firstFrame = new Promise<void>((resolve, reject) => { resolveFirst = resolve; rejectFirst = reject; });
    const stream = {
      get width() { return metadata?.width ?? 0; },
      get height() { return metadata?.height ?? 0; },
      get fps() { return metadata?.fps ?? 0; },
      get frameCount() { return frames.length; },
      get inverted() { return metadata?.inverted ?? false; },
      frames,
      writeFrameRgba(frameIndex: number, target: Uint8ClampedArray) {
        if (!metadata) invalidStream();
        const frame = frames[frameIndex];
        const pixelCount = metadata.width * metadata.height;
        if (!frame || target.length !== pixelCount * 4) invalidStream();
        for (let pixel = 0; pixel < pixelCount; pixel += 1) {
          const bit = (frame.pixels[pixel >> 3]! >> (7 - (pixel & 7))) & 1;
          const value = (bit === 1) !== metadata.inverted ? 255 : 0;
          const targetIndex = pixel * 4;
          target[targetIndex] = value;
          target[targetIndex + 1] = value;
          target[targetIndex + 2] = value;
          target[targetIndex + 3] = 255;
        }
      },
    } satisfies DecodedGhostStream;
    const consume = (): void => {
      if (!metadata && bytes.length >= STREAM_HEADER_BYTES) {
        if (bytes[0] !== 0x47 || bytes[1] !== 0x48 || bytes[2] !== 0x53 || bytes[3] !== 0x54 || bytes[4] !== 1) invalidStream();
        const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
        const width = view.getUint16(5);
        const height = view.getUint16(7);
        const fps = bytes[9]!;
        const frameCount = view.getUint16(10);
        const invert = bytes[12]!;
        if (width < 1 || width > MAX_WIDTH || height < 1 || height > MAX_HEIGHT || fps < MIN_FPS || fps > MAX_FPS || frameCount < 1 || frameCount > MAX_FRAMES || invert > 1) invalidStream();
        metadata = { width, height, fps, frameCount, inverted: invert === 1, frameBytes: Math.ceil(width * height / 8) };
      }
      if (!metadata) return;
      while (bytes.length - offset >= FRAME_HEADER_BYTES + metadata.frameBytes && frames.length < metadata.frameCount) {
        const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
        const index = view.getUint32(offset);
        const presentationTimeMs = view.getUint32(offset + 4);
        const payloadLength = view.getUint32(offset + 8);
        if (index !== frames.length || presentationTimeMs !== Math.round(index * 1000 / metadata.fps) || payloadLength !== metadata.frameBytes) invalidStream();
        const payloadStart = offset + FRAME_HEADER_BYTES;
        frames.push({ index, presentationTimeMs, pixels: bytes.slice(payloadStart, payloadStart + metadata.frameBytes) });
        offset = payloadStart + metadata.frameBytes;
        if (!started) {
          started = true;
          this.play(stream);
          resolveFirst?.();
        }
      }
    };
    void (async () => {
      try {
        while (true) {
          const result = await reader.read();
          if (result.done) break;
          totalBytes += result.value.byteLength;
          if (totalBytes > GHOST_STREAM_MAX_BYTES) throw new Error('CORPTCHA_GHOST_STREAM_TOO_LARGE');
          const combined = new Uint8Array(bytes.length + result.value.length);
          combined.set(bytes);
          combined.set(result.value, bytes.length);
          bytes = combined;
          consume();
        }
        if (!metadata || frames.length !== metadata.frameCount || offset !== bytes.length) invalidStream();
      } catch (error) {
        if (!started) rejectFirst?.(error);
        else this.stop();
      }
    })();
    return firstFrame;
  }

  stop(): void {
    if (this.handle !== undefined) {
      this.cancelFrame(this.handle);
      this.handle = undefined;
    }
    this.stream = undefined;
    this.context = undefined;
    this.image = undefined;
    this.previousTime = undefined;
  }

  destroy(): void {
    if (this.destroyed) return;
    this.stop();
    this.visibilityTarget.removeEventListener('visibilitychange', this.onVisibilityChange);
    this.destroyed = true;
  }

  private readonly onVisibilityChange = (): void => {
    if (!this.stream) return;
    if (this.visibilityTarget.visibilityState === 'hidden') {
      if (this.handle !== undefined) this.cancelFrame(this.handle);
      this.handle = undefined;
      this.previousTime = undefined;
      return;
    }
    if (this.handle === undefined) this.schedule();
  };

  private schedule(): void {
    this.handle = this.scheduleFrame(this.onAnimationFrame);
  }

  private readonly onAnimationFrame = (time: number): void => {
    this.handle = undefined;
    const stream = this.stream;
    if (!stream) return;
    const frameDuration = 1000 / stream.fps;
    if (this.previousTime === undefined || time - this.previousTime >= frameDuration) {
      this.frameIndex = (this.frameIndex + 1) % stream.frameCount;
      this.previousTime = time;
      this.drawCurrentFrame();
    }
    this.schedule();
  };

  private drawCurrentFrame(): void {
    if (!this.stream || !this.context || !this.image) return;
    this.stream.writeFrameRgba(this.frameIndex, this.image.data);
    this.context.putImageData(this.image, 0, 0);
  }
}
